import React from 'react'
type S={heading:string;text:string[]};type G={title:string;sections:S[]}
const guides:Record<string,G>={
'buy-vs-lease-vehicle-calculator':{title:'Buy Vs Lease Vehicle Calculator',sections:[
{heading:'Compare the same ownership horizon',text:['A fair lease-versus-buy comparison starts with the same number of months and the same class of vehicle. Buying creates an asset that can still have resale value at the end of the horizon; leasing usually returns the vehicle unless a purchase option is exercised. Comparing a 36-month lease with a 72-month loan by looking only at monthly payments is therefore misleading. For the purchase path, include the loan balance and expected resale value at the comparison date. For the lease path, include all payments, drive-off cash, disposition charges, and any expected end-of-lease costs.']},
{heading:'What belongs in the purchase cost',text:['The buy side is more than sticker price divided by months. Cash down, sales tax, registration, financing interest, dealer fees, maintenance, repairs, insurance differences, and depreciation all affect economic cost. Depreciation is often the largest cost during the first years of a new vehicle. A buyer also builds equity as the loan balance falls. If the vehicle is sold at the end of the analysis, net sale proceeds are resale value minus the remaining loan payoff and selling costs. That terminal value prevents the model from treating a purchased car as if it disappears.']},
{heading:'How a lease payment is built',text:['A lease payment primarily covers depreciation during the lease plus a finance charge, with taxes and fees layered on top. The negotiated capitalized cost, residual value, money factor, term, and mileage allowance matter. A high residual can reduce the depreciation portion of the payment, while a high money factor raises financing cost. Manufacturer incentives can also make a particular lease unusually attractive. When comparing a quote, use the actual due-at-signing amount and distinguish refundable security deposits from nonrefundable acquisition fees or cap-cost reductions.']},
{heading:'Mileage changes the economics',text:['Leases commonly include an annual mileage allowance and charge for excess miles. Someone driving 18,000 miles per year should not evaluate a 10,000-mile lease as if the mileage restriction has no value. Estimate total miles over the term and apply the contract excess-mile charge when appropriate. Buying has no contractual mileage penalty, but high mileage usually lowers resale value and can accelerate maintenance. The economic penalty exists on both paths; it is simply priced differently. A realistic comparison therefore links expected use to both lease charges and the buyer’s expected resale value.']},
{heading:'Cash flow versus total cost',text:['Leasing can produce a lower monthly payment because the customer finances the expected depreciation rather than the entire purchase price. Lower payment does not automatically mean lower total cost. Buying can require more cash each month yet leave the owner with a valuable vehicle after the loan is paid. Use the monthly figure for affordability and the horizon cost for economics. If one option requires a larger down payment, also consider what happens to the cash difference. Keeping that money liquid or investing it has an opportunity value that can be modeled separately.']},
{heading:'End-of-term decisions matter',text:['At lease maturity the driver may return the car, buy it for the contractual residual, or sometimes trade it. A purchase option is attractive only when the buyout price plus taxes and fees compares favorably with the vehicle’s market value and condition. A buyer, by contrast, can keep the vehicle for years after the loan ends. Long ownership periods often improve the economics of buying because the owner enjoys payment-free years, although maintenance risk rises as the vehicle ages. Run a short-horizon and long-horizon comparison if you are unsure how frequently you replace cars.']},
{heading:'Wear, maintenance, and insurance',text:['Lease contracts can charge for excess wear, missing equipment, unrepaired damage, or tires below required standards. Purchased vehicles avoid lease inspection charges but the owner absorbs all repair and resale consequences. Maintenance coverage also varies: some leases occur entirely within the factory warranty, while a long-term owner eventually pays for wear items and out-of-warranty repairs. Insurance requirements may differ because lenders and lessors can require comprehensive and collision coverage. Use quotes for the same driver and coverage limits instead of assuming insurance is identical.']},
{heading:'Taxes and fees are location-specific',text:['Vehicle sales tax treatment differs by state and sometimes by locality. Some jurisdictions tax the full purchase price, some tax lease payments, and trade-in credits can change taxable value. Registration and property-style vehicle taxes can also differ. Because these rules can move the result by hundreds or thousands of dollars, calculator estimates should be reconciled with the buyer’s order or lease worksheet before signing. The most reliable comparison uses out-the-door purchase numbers and a complete lease disclosure rather than advertised monthly payments.']},
{heading:'Worked comparison logic',text:['Suppose two options cover the same three-year period. The lease requires cash at signing and 36 payments, then a disposition fee. The purchase requires a down payment and 36 loan payments, but after month 36 the buyer still owns a car worth an estimated amount and may still owe part of the loan. Add the cash outflows for each path, then subtract the buyer’s net vehicle equity from purchase cost. If the lease has expected mileage or wear charges, add them. This framework explains why a payment comparison can reverse once residual ownership is recognized.']},
{heading:'When leasing can make sense',text:['Leasing can fit drivers who value a predictable replacement cycle, want to remain within warranty, drive a stable number of miles, and can obtain a subsidized lease with a strong residual and low money factor. It can also reduce short-term cash flow. Those benefits are real even when leasing is not the absolute cheapest lifetime strategy. The calculator should therefore support a decision, not declare one financing method universally superior. Put a dollar value on convenience only after the measurable costs are compared.']},
{heading:'When buying can make sense',text:['Buying tends to become stronger when the vehicle will be kept well beyond the finance term, annual mileage is high or unpredictable, customization matters, or the buyer wants freedom to sell at any time. A reliable used vehicle kept for many years can have a very low annualized ownership cost after the steep early depreciation period. Financing terms still matter: a high APR or very long loan can offset part of that advantage. Compare a realistic ownership period rather than assuming the car is replaced as soon as the loan ends.']},
{heading:'Mistakes that distort the answer',text:['Avoid comparing only monthly payments, ignoring cash due at signing, omitting the buyer’s resale value, assuming a lease has no maintenance or wear cost, or using an optimistic resale value with no sensitivity test. Do not count a refundable deposit as a permanent cost, and do not ignore a remaining auto-loan balance at the comparison date. Finally, avoid large lease cap-cost reductions simply to make the payment look small; if the vehicle is totaled early, the treatment of prepaid cash may be unfavorable depending on the contract and insurance settlement.']},
]},
'salary-negotiation-calculator':{title:'Salary Negotiation Calculator',sections:[
{heading:'Negotiate total compensation, not one number',text:['Base salary is the recurring foundation of an offer, but a job decision can also include target bonus, commissions, signing bonus, restricted stock, options, employer retirement contributions, health benefits, paid leave, remote-work value, and other allowances. A negotiation calculator should separate recurring compensation from one-time awards. A $15,000 signing bonus can close a first-year gap without permanently raising future salary. Conversely, a higher base can influence future percentage raises, bonus targets, retirement matches, severance, and the salary used in the next negotiation.']},
{heading:'Establish a defensible market range',text:['A useful target begins with evidence for the role, level, location, industry, and company size. Broad national averages can be poor anchors for a specialized position. Compare several sources, recent recruiter conversations, posted salary bands, and peer data where available. Then place yourself within the range based on scope, scarce skills, leadership responsibility, revenue impact, certifications, and directly relevant experience. The goal is not to find a magical market salary; it is to build a credible range that explains why your requested compensation is connected to the job’s value.']},
{heading:'Understand the value of base salary',text:['An extra dollar of base salary usually repeats every pay period and can compound through future raises. If two offers differ by $10,000 in base and both later receive 4% raises, the absolute gap grows. That makes base salary especially valuable for employees expecting to stay several years. However, cash salary can have different tax treatment and risk than equity or bonus compensation. When comparing packages, project at least two or three years rather than treating first-year total compensation as the only relevant figure.']},
{heading:'Value bonuses with probability, not optimism',text:['A target bonus is not guaranteed compensation. Ask how the plan is funded, whether payout depends on company, team, and individual performance, what percentage of employees received target in recent years, and whether the first year is prorated. For comparison, multiply an uncertain bonus by a reasonable expected payout rather than automatically counting 100%. A guaranteed first-year bonus can be treated differently from a discretionary annual award. The calculator becomes more decision-useful when guaranteed and at-risk cash are displayed separately.']},
{heading:'Treat equity as a schedule',text:['Equity value depends on grant type, vesting schedule, company value, liquidity, taxes, and forfeiture rules. A four-year RSU grant should not be counted as if the entire headline value is earned on day one. Divide expected value across vesting dates and consider what happens if you leave before a cliff. Private-company equity deserves an additional liquidity discount because a stated valuation does not guarantee a sale price. Options require attention to strike price and dilution. Negotiation can target more shares, accelerated vesting, a shorter cliff, or refresh grants—not just a larger headline grant.']},
{heading:'Use the counteroffer gap intelligently',text:['The difference between the initial offer and your target helps determine where to negotiate. If base is constrained by an internal band, a signing bonus, equity grant, guaranteed bonus, additional vacation, remote arrangement, title adjustment, or earlier compensation review may bridge part of the gap. Prioritize the items that matter most rather than asking for every possible benefit. A focused counteroffer is easier to justify: state enthusiasm, cite the role’s scope and your relevant value, give a specific target, and then allow the employer to respond.']},
{heading:'Account for switching costs',text:['Changing jobs can create costs that a salary headline hides: forfeited bonus, unvested equity, retirement-match vesting, relocation, commuting, health-plan differences, childcare changes, or a gap between paychecks. A make-whole signing bonus can compensate for a bonus or equity award you are leaving behind. Calculate those losses explicitly and document them where appropriate. If a new role pays more but requires expensive commuting or relocation, compare after-cost compensation rather than gross salary alone.']},
{heading:'Compare benefits on an annual basis',text:['Employer health premiums, HSA contributions, 401(k) matching, pension credits, life and disability insurance, paid parental leave, and paid time off have economic value. Some benefits are difficult to monetize precisely, but large differences should not be ignored. For a retirement match, estimate the employer dollars you realistically expect to receive. For health insurance, compare employee premiums and likely out-of-pocket exposure. For paid leave, consider whether extra days are actually usable. Keep subjective perks separate from cash so the model remains transparent.']},
{heading:'A practical offer comparison',text:['Imagine Offer A has a $130,000 base, 10% target bonus, and modest equity, while Offer B has a $120,000 base, a $20,000 signing bonus, and larger four-year equity. Offer B may lead in year one because of the signing payment, while Offer A may lead in later recurring cash. Project each year using vesting and bonus assumptions. Then test a departure after two years. This exposes how cliffs and one-time payments affect realized compensation and prevents a large headline package from obscuring the timing of what you actually earn.']},
{heading:'Negotiation timing and communication',text:['The strongest time to negotiate is generally after an offer exists and before acceptance, when both sides know there is mutual interest. Ask for the complete package in writing before countering. Avoid inventing competing offers or unsupported market claims. Explain the request through role scope, market evidence, and the value you can deliver. A precise request such as a base range or a specific signing amount is easier to evaluate than saying the offer is simply too low. Keep the tone collaborative because the objective is an improved agreement, not winning an argument.']},
{heading:'Know your walk-away point',text:['Before negotiating, decide the minimum package that makes the move worthwhile. That threshold can reflect current compensation, risk, career growth, work arrangement, commute, benefits, and personal priorities. Separating target, acceptable, and walk-away levels prevents emotion from changing the decision after a recruiter calls. It also makes tradeoffs clearer: you may accept a slightly lower base for a materially better role or reject a higher package if the hours and risk are unacceptable. The calculator quantifies compensation; it cannot decide how you value the job itself.']},
{heading:'Common valuation errors',text:['Do not add four years of equity to one year of salary, count a target bonus as guaranteed, ignore vesting cliffs, or compare gross compensation while overlooking a major health-premium difference. Do not assume a startup option grant equals the number of options times the latest preferred-share price. Avoid anchoring solely on your current salary when the new role has a different market value. And do not negotiate from a fabricated competing offer. The most credible analysis uses comparable time periods, probability-adjusted variable pay, and clearly separated assumptions.']},
]},
'athletic-performance-calculator':{title:'Athletic Performance Calculator',sections:[
{heading:'Performance scores need sport context',text:['Athletic performance cannot be reduced to one universal score. Sprint speed, aerobic capacity, power-to-weight ratio, jump height, strength, agility, and endurance matter differently in a 100-meter sprint, soccer match, marathon, or powerlifting meet. Use the calculator’s output as a structured snapshot of the inputs it actually measures, then interpret those outputs against the demands of the athlete’s sport, position, age, sex, training history, and testing protocol. A change is meaningful only when the same test is repeated under comparable conditions.']},
{heading:'Speed and pace are related but read differently',text:['Speed expresses distance per unit of time, while pace expresses time per unit of distance. A faster athlete has higher speed but lower pace. Small timing errors matter greatly over short sprints, so hand timing and electronic timing should not be mixed casually. For running tests, record the exact distance, surface, footwear, start method, and environmental conditions. If the calculator converts between speed units, verify that meters, kilometers, miles, seconds, minutes, and hours are entered consistently before comparing sessions.']},
{heading:'Power-to-weight can reveal useful changes',text:['Absolute power matters for tasks such as throwing or moving an external load, while power relative to body mass can be more informative for climbing, jumping, accelerating, and many endurance settings. Losing body mass can improve a ratio without increasing actual power; gaining muscle can lower a ratio temporarily while improving absolute force. Track the numerator and denominator as well as the ratio. A better score is most valuable when it corresponds with better sport performance rather than being pursued as an isolated number.']},
{heading:'Heart-rate metrics have uncertainty',text:['Estimated maximum heart rate formulas describe populations and can be wrong for an individual by a meaningful margin. Training zones based on an estimated maximum should therefore be treated as approximate. Resting heart rate also varies with sleep, illness, hydration, temperature, medications, stress, and accumulated training fatigue. Compare trends from measurements taken under similar conditions instead of reacting to one unusual reading. Athletes with symptoms or medical concerns should use clinical guidance rather than a fitness calculator to determine safe exercise intensity.']},
{heading:'VO2 max estimates are protocol dependent',text:['Direct VO2 max requires laboratory gas analysis; field tests and wearable devices estimate it from performance or physiological signals. Two methods can give different numbers for the same athlete. The useful question is often whether an estimate improves under the same protocol, not whether it matches a laboratory value exactly. When comparing athletes, account for whether VO2 max is expressed in absolute liters per minute or relative milliliters per kilogram per minute, because body mass changes the interpretation.']},
{heading:'Strength numbers need normalization',text:['A one-repetition maximum, estimated 1RM, or lifting total can describe absolute strength, but comparisons across body sizes often use strength relative to body mass. Rep-based 1RM formulas become less reliable as the repetition count rises or technique changes. Use controlled sets performed close enough to maximal effort for the chosen formula, and do not treat an estimated maximum as a command to attempt that load. Exercise selection, range of motion, equipment, and judging standards should remain consistent across tests.']},
{heading:'Jump and sprint tests are sensitive to technique',text:['Vertical-jump results depend on whether an arm swing, countermovement, or approach is allowed. Sprint results depend on start position, timing gates, surface, wind, and footwear. Improvement caused by learning the test is still real test improvement, but it is not identical to a physiological gain. Record the protocol beside the result. If a team uses the calculator for monitoring, standardize warm-up, rest intervals, equipment, and number of attempts so changes are easier to interpret.']},
{heading:'Training load is not performance itself',text:['More training is not automatically better. Performance emerges from training stimulus plus recovery, and excessive load can temporarily suppress test results. A poor session after a hard training block may reflect fatigue rather than lost fitness. Conversely, a personal best after a taper does not mean the preceding workload was unnecessary. Use calculator metrics alongside session RPE, volume, sleep, soreness, and competition results. The goal is to connect numbers to a training decision, not maximize every metric simultaneously.']},
{heading:'Use repeated measurements to find signal',text:['Day-to-day biological and measurement noise can be larger than the change an athlete hopes to detect. Take multiple trials where appropriate and use the same device and protocol. For metrics that vary naturally, a rolling trend can be more informative than a single reading. If a sprint time changes by only a few hundredths of a second, ask whether the timing system is precise enough to support that conclusion. Meaningful progress should exceed normal testing variation or be supported by repeated observations.']},
{heading:'Build a sport-specific dashboard',text:['Choose a small set of metrics that map to the athlete’s actual demands. A field-sport player might track acceleration, repeated-sprint ability, jump performance, and aerobic fitness; an endurance athlete might emphasize pace at a standard effort, threshold markers, and race performance; a strength athlete may focus on competition lifts and relative strength. Keeping every available metric can create noise. A good dashboard tells a coherent story about readiness and adaptation.']},
{heading:'Avoid unsafe interpretation',text:['A calculator cannot diagnose overtraining, cardiovascular disease, injury, eating disorders, or other medical conditions. Sudden unexplained performance decline, chest pain, fainting, severe shortness of breath, or persistent symptoms warrant appropriate professional evaluation. Youth athletes also require age-appropriate interpretation because growth and maturation can change body size and performance rapidly. Use performance calculations for training analysis, not as a substitute for coaching judgment or healthcare.']},
{heading:'A useful worked review',text:['Suppose an athlete becomes lighter, improves a jump test, and runs the same sprint time. Relative power may rise because body mass fell, but the unchanged sprint suggests the transfer to acceleration is uncertain. If resting heart rate is also elevated after a heavy training week, repeating the tests after recovery may be more informative than changing the program immediately. This kind of multi-metric interpretation is stronger than labeling every increase as good and every decrease as bad.']},
]},
'debt-to-income-optimizer':{title:'Debt-to-Income Optimizer',sections:[
{heading:'Debt-to-Income Optimizer — topic 1',text:['DTI compares recurring monthly debt obligations with gross monthly income. Mortgage underwriting often distinguishes front-end housing ratio from back-end total DTI. The denominator is gross income, not take-home pay, while the numerator typically includes required debt payments reported or documented for underwriting. Credit-card minimums, auto loans, student loans, alimony where applicable, and the proposed housing payment can matter. Utilities and groceries normally are not DTI debts, even though they still matter to affordability.']},
{heading:'Front-end versus back-end DTI',text:['Front-end DTI isolates the proposed housing expense relative to gross income; back-end DTI adds other recurring debt. A borrower can have a comfortable housing ratio but a weak back-end ratio because of auto, student, or revolving debt. When a lender discusses a DTI ceiling, ask which ratio and which loan program is meant. Government-backed and conventional programs can use different underwriting rules, and automated underwriting can consider compensating factors beyond one published percentage.']},
{heading:'How rate changes alter DTI without new debt',text:['Mortgage DTI can change when interest rates move because the proposed principal-and-interest payment changes even if home price and down payment do not. A borrower near a ratio limit may qualify at one rate and miss it after rates rise. Re-run the housing payment with the actual quoted rate and include taxes, insurance and HOA. Buying points can lower payment, but compare the cash cost of points with the underwriting benefit and expected holding period rather than paying fees solely to force a ratio below a line.']},
{heading:'Income qualification can be the hidden constraint',text:['Salary is straightforward when stable, but overtime, bonus, commission, rental, alimony, or self-employment income can require history and documentation before a lender counts it. Increasing a calculator income field to include every dollar received can make the modeled DTI look better than the underwritten ratio. For a preapproval decision, use income the lender is likely to qualify, not merely household cash inflow. If uncertain, ask the loan officer which monthly income figure appears in underwriting.']},
{heading:'Payoff versus paydown',text:['Paying a debt down does not always lower its contractual monthly payment. Many installment loans keep the scheduled payment unchanged after an extra principal payment, so DTI may not improve unless the balance is fully paid or the lender recasts the loan. Revolving minimum payments can fall as balances decline, but the timing and formula vary. Before moving cash, confirm whether the action actually changes the payment used in underwriting. A large principal reduction with no payment change may improve net worth without changing DTI.']},
{heading:'Credit score and DTI are separate',text:['A debt payoff can influence both DTI and credit, but they are different underwriting dimensions. DTI measures monthly obligations relative to income; credit scores reflect information in credit reports using scoring models. Closing an old card, opening a new consolidation loan, or sharply changing utilization can affect credit even when DTI improves. Mortgage pricing can be sensitive to credit score, so optimize the whole application rather than one ratio in isolation.']},
{heading:'Target the mortgage payment, not just the ratio',text:['If the purpose is home shopping, reverse the DTI formula to estimate the maximum housing payment consistent with a chosen back-end ratio after existing debts are subtracted. Then translate that housing budget into principal and interest only after reserving property tax, homeowners insurance, HOA dues, and mortgage insurance. This avoids the common error of treating the entire DTI allowance as mortgage principal-and-interest capacity. Property-level costs can consume a large share of the housing payment.']},
{heading:'Debt-to-Income Optimizer — topic 2',text:['Optimization means identifying which payment reduction creates the most underwriting room per dollar of cash used. Paying off a small installment balance can eliminate an entire monthly payment, while making the same cash payment against a large loan may barely change its required payment. Credit-card payoff can reduce reported minimums, but the exact update timing depends on statement cycles and credit reporting. Do not close accounts merely to improve DTI without considering credit effects.']},
{heading:'Debt-to-Income Optimizer — topic 3',text:['For a mortgage scenario, calculate gross monthly income from stable qualifying sources and list required monthly debts. Add the proposed principal, interest, property tax, homeowners insurance, HOA dues, and mortgage insurance where relevant. Divide total monthly obligations by gross monthly income. A borrower earning $10,000 gross monthly with $1,000 of existing debt and a $3,000 proposed housing payment has a 40% back-end DTI. Reducing an auto payment by $500 would lower that modeled ratio to 35%.']},
{heading:'Debt-to-Income Optimizer — topic 4',text:['Student-loan treatment is especially important because the payment used by a lender may not equal the amount a borrower informally expects to pay. Rules can differ by loan program, documentation, deferment status, and repayment plan. Similarly, self-employed income may be underwritten from tax-return calculations rather than current business deposits. A calculator can model arithmetic, but the lender determines qualifying income and debt treatment.']},
{heading:'Debt-to-Income Optimizer — topic 5',text:['DTI is an eligibility metric, not a complete household budget. A borrower can meet an underwriting ratio and still feel cash-flow pressure because taxes, childcare, healthcare, utilities, food, transportation, savings, and irregular expenses consume take-home pay. Use DTI optimization alongside an after-tax budget and emergency-fund plan. The objective should be sustainable borrowing, not merely reaching the highest mortgage amount a formula permits.']},
{heading:'Debt-to-Income Optimizer — topic 6',text:['Before paying debt solely to qualify, ask a lender how that debt will be treated and whether payoff must occur before closing. Compare the cash used for payoff with cash needed for down payment, closing costs, reserves, moving expenses, and repairs. Sometimes preserving reserves is more valuable than forcing the ratio lower. In other cases, eliminating one monthly obligation can materially improve approval odds or pricing.']},
{heading:'Debt-to-Income Optimizer — topic 7',text:['Avoid manipulating the model by excluding debts that will be visible to underwriting, using net income in the denominator, or assuming a future raise that cannot be documented. Co-signed obligations may count unless program rules allow exclusion with evidence another party pays them. New debt opened before closing can also change the ratio. Recalculate after major credit changes and before making large financed purchases.']},
{heading:'Debt-to-Income Optimizer — topic 8',text:['The most useful output is the monthly-payment reduction needed to reach a target DTI. Rearranging the ratio shows the maximum total monthly debt allowed at a chosen percentage: target DTI multiplied by gross monthly income. Subtract proposed housing expense and other unavoidable obligations to see how much room remains. That turns a percentage into an actionable payoff target.']},
]},
'charitable-bunching-calculator':{title:'Charitable Bunching Calculator',sections:[
{heading:'Charitable Bunching Calculator — topic 1',text:['Charitable bunching concentrates donations that might normally be made over several years into one tax year. The strategy is designed for taxpayers whose itemized deductions hover near the standard deduction. If annual itemized deductions never exceed the standard deduction, charitable gifts may not create an incremental federal income-tax deduction. Combining multiple years of gifts can push deductions above the threshold in the contribution year, followed by standard-deduction years.',
{heading:'Standard deduction creates the threshold effect',text:['The tax advantage of bunching comes from a threshold. If non-charitable itemized deductions plus normal annual gifts already exceed the standard deduction, moving gifts between years may create little extra federal deduction. If they sit below it, part of each annual gift can be economically hidden by the standard deduction. Concentrating gifts can make more of the charitable amount incremental in the bunching year. Calculate the deduction actually used under each strategy rather than multiplying total donations by a tax rate.']},
{heading:'Cash versus appreciated property',text:['Cash is simple to value, but donating long-held appreciated securities can avoid selling the asset first. If a donor sells, realizes a gain, and then gives cash, capital-gains tax may be triggered before the charitable deduction. Direct donation can be more tax-efficient when the charity or DAF sponsor accepts the asset and the donor satisfies applicable requirements. Short-term property, closely held interests, crypto, and other noncash assets can have different valuation and deduction rules, so do not apply stock assumptions universally.']},
{heading:'AGI limits can defer deductions',text:['Charitable deductions can be limited to percentages of adjusted gross income depending on the property and recipient. Excess qualifying contributions may be carried forward under applicable rules rather than fully deducted in the bunching year. A very large DAF contribution can therefore fail to create the immediate deduction suggested by a simple calculator. High-value bunching plans should test whether the intended contribution fits within current-year limits and how any carryforward interacts with later deductions.']},
{heading:'Timing around a liquidity event',text:['Bunching can be especially relevant in a year with unusually high taxable income from a business sale, large bonus, equity event, or Roth conversion because the donor may face a higher marginal rate. That does not mean a donation should be accelerated solely for tax reasons. Compare the tax value with cash needs, the donor’s philanthropic schedule, deduction limits, and the possibility that future income will also be high. A DAF can preserve a steady grant schedule while moving the contribution date.']},
{heading:'Measure after-tax cost of giving',text:['A $20,000 charitable contribution never becomes free because it creates a deduction. If the incremental deduction saves $6,000 of tax, the household still has a $14,000 after-tax economic cost, ignoring investment effects. This framing keeps the purpose clear: bunching can make planned generosity more tax-efficient, but it does not turn spending into profit. Compare strategies holding the intended charitable support constant so the calculator does not reward a plan merely because it gives less.']},]},
{heading:'Charitable Bunching Calculator — topic 2',text:['The correct comparison is multi-year. Add deductible charitable gifts to other itemized deductions expected for each year, subject to applicable tax rules and limitations. Compare itemizing with taking the standard deduction in each year. Then compare that baseline with a bunching pattern over the same horizon. The potential tax benefit is the difference in deductions that actually reduce taxable income, multiplied only approximately by the relevant marginal tax rate. A deduction does not return the donated dollar; it reduces taxable income.']},
{heading:'Charitable Bunching Calculator — topic 3',text:['A donor-advised fund can separate the timing of the tax deduction from the timing of grants to operating charities. A donor may contribute several years of intended giving to the DAF in one year, potentially claim a deduction then, and recommend grants to charities over later years. The contribution to the DAF is generally irrevocable, and the sponsoring organization controls the assets subject to advisory privileges. Fees, investment options, minimum grants, and sponsoring-organization policies should be reviewed before using a DAF.']},
{heading:'Charitable Bunching Calculator — topic 4',text:['Appreciated securities can add another layer. Donating eligible long-held appreciated assets directly may allow a deduction based on fair market value while avoiding realization of embedded capital gain, subject to tax rules and percentage limitations. Selling the asset first and donating cash can trigger capital-gains tax. The calculator should not assume every asset or every donation receives identical treatment; property type, holding period, recipient organization, adjusted gross income limits, and substantiation requirements matter.']},
{heading:'Charitable Bunching Calculator — topic 5',text:['Suppose a household expects $18,000 of non-charitable itemized deductions each year and would normally donate $10,000 annually. If the applicable standard deduction is above $28,000, itemizing may provide little or no incremental benefit. Contributing $30,000 in one year instead could produce $48,000 of itemized deductions that year, followed by two years using the standard deduction. The exact benefit depends on the actual deduction thresholds and tax situation for those years, so the arithmetic should be updated rather than relying on stale limits.']},
{heading:'Charitable Bunching Calculator — topic 6',text:['Bunching is not automatically superior. A household with mortgage interest, state and local taxes subject to applicable limits, medical deductions, or other itemized deductions already far above the standard deduction may receive a deduction for charitable giving without bunching. A taxpayer with insufficient taxable income or deduction limitations may also realize less benefit than a simple marginal-rate estimate suggests. Charitable intent should remain primary; tax timing is an optimization around giving that would otherwise occur.']},
{heading:'Charitable Bunching Calculator — topic 7',text:['Keep records. Cash contributions generally require appropriate bank records or written acknowledgments, and larger noncash gifts can require additional substantiation or appraisal. DAF receipts document the contribution to the sponsoring organization; later grants from the DAF are not a second personal charitable deduction. Do not double-count them in a model. Also avoid treating a pledge as deductible before a qualifying contribution is actually made.']},
{heading:'Charitable Bunching Calculator — topic 8',text:['Because standard deductions, tax brackets, charitable limits, and other rules can change, a calculator labeled for a specific year should use that year’s rules and filing status. For a bunching plan spanning several future years, run sensitivity cases instead of assuming every threshold remains fixed. The strategy is most useful when the deduction advantage is large enough to justify the administrative complexity and still fits the donor’s cash-flow and philanthropic goals.']},
]},
'real-estate-appreciation-calculator':{title:'Real Estate Appreciation Calculator',sections:[
{heading:'Real Estate Appreciation Calculator — topic 1',text:['Real-estate appreciation measures the change in property value over time. If a home rises from $400,000 to $500,000, the total appreciation is $100,000 or 25%. Annualized appreciation is different: it asks what compounded yearly rate would turn the starting value into the ending value over the holding period. For multi-year comparisons, compound annual growth rate is usually more meaningful than dividing the total percentage gain by the number of years.',
{heading:'CAGR from a known sale history',text:['When both starting and ending values are known, annualized appreciation can be solved as ending value divided by starting value, raised to one over the number of years, minus one. A property rising from $300,000 to $450,000 over ten years appreciated 50% in total, but the compound annual rate is about 4.14%, not 5%. CAGR is useful for comparing holding periods of different lengths because it converts the full change into an equivalent compounded yearly rate.',
{heading:'Do not infer a forecast from a short recent period',text:['A one-year price jump can produce an extreme annual rate that is unsuitable for a ten-year projection. Housing cycles reflect credit conditions, construction, migration and local employment, and recent growth can mean-revert. When selecting an assumption, review several horizons and local repeat-sales or comparable-sale evidence. If a decision only works when the most recent boom rate continues for years, the plan is highly sensitive to appreciation and should be tested with slower growth.']},]},
{heading:'Selling costs can absorb appreciation',text:['A property can show a positive market-value gain yet produce little net sale profit after brokerage, transfer taxes, concessions, repairs, and other closing costs. Short holding periods are especially sensitive because transaction costs are large relative to modest appreciation. If the calculator projects a future value, separately estimate net sale proceeds by subtracting expected selling costs and mortgage payoff. That is the cash available to the owner; future market value by itself is not spendable equity.']},
{heading:'Mortgage amortization creates equity without appreciation',text:['Home equity can increase even if the property value is flat because scheduled mortgage payments reduce principal. Conversely, a property can appreciate while the owner has little equity if leverage is high or additional borrowing is added. When the planning question is future equity rather than future property value, combine the appreciation model with an amortization schedule. Keeping these drivers separate clarifies whether projected wealth comes from market growth, debt repayment, or additional cash invested.']},
{heading:'Property taxes can respond to value differently',text:['A higher market value does not always translate immediately into a proportional property-tax increase. Assessment systems, homestead rules, caps, reassessment events, and local millage rates vary widely. A long-range ownership-cost projection should therefore not multiply future market value by today’s effective tax rate without checking local rules. Appreciation calculators are strongest when they stay focused on value growth and leave jurisdiction-specific tax projections to a separate, explicit assumption.']},
{heading:'Scenario ranges are more credible than one forecast',text:['Housing appreciation is lumpy. Instead of entering one optimistic rate and reading the future value as expected, compare flat, modest, and stronger growth cases. For a leveraged purchase, also test a decline during the first few years because an owner forced to sell can face negative equity after transaction costs even if the long-term regional trend is positive. The sensitivity range is often more decision-useful than the midpoint because it reveals how dependent the plan is on price growth.']},]},
{heading:'Real Estate Appreciation Calculator — topic 2',text:['Future value under a constant annual appreciation assumption is starting value multiplied by one plus the annual rate raised to the number of years. A $400,000 property growing at 3% for ten years is modeled at about $537,600, not $520,000, because each year’s growth builds on the prior year. This is a scenario, not a forecast. Actual housing markets move unevenly and can decline for long periods.']},
{heading:'Real Estate Appreciation Calculator — topic 3',text:['Nominal appreciation should be separated from inflation. If a property gains 4% annually while general prices rise 3%, the real increase in purchasing power is much smaller than 4%. Local housing can also diverge sharply from national inflation because supply constraints, employment, migration, interest rates, taxes, insurance costs, school quality, and neighborhood changes affect demand. Use local comparable-sales evidence when estimating current value rather than applying a national average mechanically.']},
{heading:'Real Estate Appreciation Calculator — topic 4',text:['Appreciation is not the same as investment return. A homeowner may use leverage, pay mortgage interest, property tax, insurance, maintenance, HOA dues, transaction costs, and improvements. A rental property can also produce net operating income. Selling incurs brokerage and closing costs and may create taxes. A property that appreciates strongly can still have a mediocre total return if carrying costs are high, while a modestly appreciating rental can perform well because of cash flow and principal paydown.']},
{heading:'Real Estate Appreciation Calculator — topic 5',text:['Renovations complicate the interpretation of appreciation. If a home bought for $400,000 later sells for $550,000 after $80,000 of capital improvements, the $150,000 price difference is not purely market appreciation. Part of the higher value may reflect additional capital invested. Track major improvements separately when evaluating investment performance or cost basis. Ordinary maintenance may preserve value without creating an equivalent dollar-for-dollar increase.']},
{heading:'Real Estate Appreciation Calculator — topic 6',text:['Leverage magnifies equity outcomes. A 5% rise in property value can represent a much larger percentage gain on the owner’s initial equity, but mortgage debt and transaction costs remain. The same leverage magnifies losses when prices fall. Do not describe appreciation rate as return on cash invested unless the financing and all cash flows are explicitly included.']},
{heading:'Real Estate Appreciation Calculator — topic 7',text:['For planning, run several appreciation paths: flat prices, a conservative positive rate, and a stronger rate supported by local history. Also test a temporary decline early in the holding period if a sale date is inflexible. A long horizon can absorb volatility better than a forced sale after one or two years because buying and selling costs are large relative to small price changes.']},
{heading:'Real Estate Appreciation Calculator — topic 8',text:['Historical appreciation is backward-looking. A neighborhood that grew rapidly because rates were low or supply was constrained may not repeat that pace. Conversely, a weak recent period does not guarantee continued weakness. The calculator is best used to understand how different growth assumptions affect future value and equity, then combined with market research rather than presented as a price prediction.']},
]},
'code-minifier':{title:'Code Minifier',sections:[
{heading:'What minification actually removes',text:['Minification reduces transfer size by removing characters that are unnecessary for execution or rendering, such as comments, optional whitespace, and in some languages safely reducible syntax. It is different from compression: gzip or Brotli encode the transmitted bytes, while minification changes the source representation itself. Production sites commonly use both. A 100 KB JavaScript file may become smaller after minification and smaller again when the web server compresses the minified response. Measure the final transferred size rather than assuming one technique replaces the other.']},
{heading:'JavaScript needs parser-aware tooling',text:['JavaScript cannot be safely minified by deleting every space or line break. Automatic semicolon insertion, regular-expression literals, template strings, comments, and token boundaries can change program meaning. Advanced minifiers parse the program into an abstract syntax tree, transform it, and print a compact equivalent. Some also shorten local variable names or remove unreachable code. For important production bundles, use a mature parser-based minifier and run tests against the minified build. A lightweight browser tool is useful for snippets but should not be mistaken for a full build optimizer.']},
{heading:'CSS minification has its own rules',text:['CSS can often lose comments, indentation, extra spaces, and redundant semicolons without changing rendering, but values and custom-property contents still need correct tokenization. Build tools may additionally normalize colors, merge rules, or remove duplicate declarations; those are optimizations beyond basic minification and can be riskier. Test responsive states, pseudo-classes, animations, and browser-specific declarations after aggressive transformations. If source order is intentionally resolving the cascade, a tool that reorders rules can alter the design even when the stylesheet remains syntactically valid.']},
{heading:'HTML whitespace can be meaningful',text:['HTML minification is not simply deleting all whitespace between tags. Spaces inside text nodes can separate words, preformatted content must preserve layout, and inline elements can rely on whitespace for visual separation. Script, style, textarea, and pre elements require special handling. Attribute quoting can sometimes be omitted under HTML rules, but a conservative minifier may retain it for clarity and safety. Validate the output in the target browsers, especially when templates or server-side placeholders are present.']},
{heading:'Comments are not always disposable',text:['Most comments are safe to remove from production assets, but license banners, copyright notices, source-map directives, conditional constructs in legacy environments, or tool-specific annotations can matter. JavaScript packages sometimes use comments beginning with an exclamation mark to mark licenses that must be preserved. Before stripping comments from third-party code, check the package license and build configuration. Minification should reduce noise without accidentally removing legally required attribution or instructions consumed by another tool.']},
{heading:'Minification does not provide secrecy',text:['Compact code is harder to read casually, but it is still delivered to the browser and can be formatted again. Variable mangling is not encryption. API keys, private credentials, signing secrets, database passwords, and privileged business logic must not be placed in client-side JavaScript merely because a minifier obscures them. Anyone who can download the bundle can inspect strings, network calls, and runtime behavior. Treat minification as a performance technique, not a security control.']},
{heading:'Source maps restore debuggability',text:['Production minification can make stack traces point to a single compressed line with shortened identifiers. Source maps connect generated positions back to original source files and are valuable for error monitoring. Decide whether maps should be publicly downloadable, uploaded privately to an error-tracking service, or omitted based on your threat model and debugging needs. If maps are deployed, verify that their URLs and release versions match the exact minified assets; mismatched maps can make debugging more confusing than having none.']},
{heading:'Measure the right performance impact',text:['A smaller source file usually helps network transfer, especially on slow connections, but parse and execution cost also matter for JavaScript. Tree shaking, code splitting, dead-code elimination, image optimization, caching, and Brotli compression can produce larger gains than whitespace removal alone. Compare original bytes, minified bytes, compressed transfer bytes, and loading metrics. If a file is tiny or already generated in compact form, additional minification may provide negligible benefit.']},
{heading:'Keep a readable source of truth',text:['Do not edit minified output by hand. Keep readable source code in version control and generate production assets through a reproducible build. That makes code review, testing, source maps, and future changes manageable. If this browser tool is used for a one-off snippet, save the original before replacing anything. A minifier should be the final transformation in a workflow, not the only copy of code you own.']},
{heading:'Validate after transformation',text:['For JavaScript, run unit and integration tests and exercise code paths affected by build-time constants or environment flags. For CSS, visually test representative pages and breakpoints. For HTML, validate forms, text spacing, embedded scripts, and structured data. Compare console errors and network requests before and after minification. The smaller output is useful only if behavior is preserved. When a transformation breaks code, restore the original and reduce the aggressiveness rather than patching the compressed file.']},
{heading:'Minification and bundling are separate',text:['Bundling combines modules into one or more deployable assets; minification makes those assets compact. Modern applications often split bundles by route or feature so users download only what they need. A single heavily minified mega-bundle can still perform worse than smaller route-level chunks. Evaluate caching too: changing one line in a huge bundle can invalidate the entire cached asset, while stable vendor chunks may remain reusable.']},
{heading:'Privacy advantage of local processing',text:['When a minifier runs entirely in the browser, source code can remain on the user’s device instead of being uploaded to a remote service. That is valuable for proprietary snippets, but users should still confirm the tool’s implementation and network behavior before processing confidential code. Browser extensions, analytics scripts, or compromised dependencies can affect privacy independently of the minification algorithm. For highly sensitive code, an audited local build tool remains the stronger choice.']},
]},
'aspect-ratio-calculator':{title:'Aspect Ratio Calculator',sections:[
{heading:'Aspect ratio describes shape, not size',text:['An aspect ratio is the proportional relationship between width and height. A 1920×1080 frame and a 1280×720 frame are both 16:9 even though they contain different numbers of pixels. That makes ratio useful when resizing images, video, canvases, presentations, and responsive containers without changing their shape. The ratio can be written as width:height or as a decimal width divided by height. Resolution, pixel density, and file size are separate properties.']},
{heading:'Reduce a ratio with the greatest common divisor',text:['To simplify pixel dimensions into a ratio, divide width and height by their greatest common divisor. For 1920 and 1080, the greatest common divisor is 120, producing 16 and 9. Not every image reduces to a familiar standard such as 4:3 or 16:9; an unusual crop can have a perfectly valid uncommon ratio. Rounding a decimal ratio too early can incorrectly label near-matches, so preserve the integer dimensions when exactness matters.']},
{heading:'Find a missing dimension',text:['When the ratio and one dimension are known, proportional scaling finds the other. For a ratio W:H and a target width w, target height equals w × H/W. For a target height h, target width equals h × W/H. A 16:9 image resized to 800 pixels wide therefore needs a height of 450 pixels. If the result is fractional, round according to the destination requirements and understand that one-pixel rounding can make the final ratio slightly imperfect.']},
{heading:'Cropping differs from stretching',text:['If source and destination ratios differ, there are three broad choices: crop part of the source, add empty space such as letterboxing, or distort the image by scaling width and height independently. Cropping preserves geometry but removes content. Letterboxing preserves all content but adds bars or background. Stretching keeps every pixel but changes shapes and is usually undesirable for photographs and video. The calculator tells you the geometric mismatch; the appropriate remedy depends on the content and platform.']},
{heading:'Common video formats',text:['16:9 is common for widescreen video and modern displays, 9:16 is its portrait counterpart used by many vertical-video platforms, 4:3 remains common in older media and some creative formats, and cinematic presentations may use wider ratios such as 2.39:1. Platform recommendations can change and may depend on placement. Use the ratio to preserve composition, then verify current resolution, duration, codec, and safe-area requirements with the destination platform.']},
{heading:'Images for responsive web design',text:['Responsive layouts often reserve space before an image loads to reduce layout shift. CSS aspect-ratio can define that shape independently of the eventual pixel resolution. An image displayed in a 16:9 container should ideally be cropped or supplied in a matching ratio so object-fit behavior does not remove important content unexpectedly. For high-density screens, choose enough source pixels for the largest rendered size, but do not confuse doubling resolution with changing aspect ratio.']},
{heading:'Print adds physical dimensions and DPI',text:['A ratio remains the same whether dimensions are pixels, inches, or centimeters, but print quality introduces pixels per inch. A 3:2 image can print at 6×4 inches, 12×8 inches, or many other sizes while preserving shape. The required pixel dimensions depend on the chosen PPI. For example, a 6×4 inch print at 300 PPI needs 1800×1200 pixels. Ratio controls shape; PPI and pixel count control detail at a physical size.']},
{heading:'Social-media crops need safe composition',text:['A photo may be reused in square, portrait, landscape, and story placements. Converting ratios by cropping can cut off faces, text, logos, or products near the edges. Keep critical content within a safe central region or create separate crops for important placements. When a platform automatically crops thumbnails, preview the actual placement rather than assuming the uploaded master ratio will be displayed everywhere.']},
{heading:'Pixel aspect ratio is a different concept',text:['Most modern digital images use square pixels, so display aspect ratio follows pixel dimensions directly. Some legacy video formats use non-square pixel aspect ratios, where stored resolution and displayed shape differ. In those workflows, width divided by height alone does not fully describe the intended display. Professional video conversion may require sample-aspect-ratio or display-aspect-ratio metadata. A basic image ratio calculator normally assumes square pixels unless it explicitly supports these formats.']},
{heading:'A worked crop calculation',text:['Suppose a 4000×3000 photograph, which is 4:3, must fill a 16:9 frame without bars. Keeping the full 4000-pixel width means a 16:9 crop height of 2250 pixels, so 750 vertical pixels must be removed in total. If the subject is centered, that could mean roughly 375 pixels from the top and bottom. Alternatively, keeping all 3000 pixels of height would require a width of about 5333 pixels, which the source does not have, so padding would be necessary.']},
{heading:'Rounding and encoder constraints',text:['Some video encoders and image pipelines prefer or require even-numbered dimensions because of chroma subsampling or codec block structures. A proportional calculation might return 853×480 for a 16:9 approximation, but 854×480 may be more practical for encoding. The resulting ratio is extremely close rather than mathematically exact. Choose dimensions that satisfy the production system and document whether the goal is exact geometry or a conventional near-equivalent resolution.']},
{heading:'Typical mistakes',text:['Do not treat 1920×1080 and 1920×1200 as the same ratio simply because both are widescreen. Do not swap width and height when moving between landscape and portrait; 16:9 becomes 9:16. Avoid resizing both dimensions independently unless distortion is intentional. And do not use aspect ratio to infer image quality: a perfectly proportioned image can still be too low-resolution, heavily compressed, or blurred for the intended display.']},
]},
'loan-origination-fee-calculator':{title:'Loan Origination Fee Calculator',sections:[
{heading:'Loan Origination Fee Calculator — topic 1',text:['An origination fee is an upfront charge associated with making a loan and is often quoted as a percentage of the loan amount or as points. One point equals 1% of the loan amount. On a $300,000 loan, one point is $3,000. The fee can be paid in cash, deducted from proceeds, financed into the balance when allowed, or economically offset by a higher interest rate or lender credit. Those choices have different cash-flow consequences.',
{heading:'Points should be converted to dollars',text:['A percentage fee becomes easier to compare once converted into cash. Multiply loan amount by the fee percentage: 0.75 points on a $400,000 mortgage equals $3,000. If the loan amount itself changes between offers, comparing only points can be misleading because the dollar fee changes. Keep lender charges separate from title, appraisal, taxes, insurance prepaids, and escrow deposits so the fee analysis answers the intended pricing question.',
{heading:'APR and break-even answer different questions',text:['APR compresses certain loan costs into an annualized disclosure measure under standardized assumptions, while break-even asks when one option’s cumulative cash savings recover its extra upfront cost. Both are useful. APR helps screen comparable loans; break-even helps a borrower with a known expected holding period. When the two appear to point in different directions, inspect loan term, fee treatment and payoff assumption rather than choosing one metric mechanically.']},]},
{heading:'Net proceeds matter for personal loans',text:['Some personal lenders deduct the origination fee before sending funds. A $25,000 note with a 5% withheld fee can deliver only $23,750 before other adjustments. If the borrower needs $25,000 to consolidate debt, the requested principal must be higher, which also changes interest and payment. Compare offers using the amount of usable cash required, not simply the face amount advertised on the loan agreement.']},
{heading:'Early payoff raises the effective cost of upfront fees',text:['An upfront fee is paid regardless of whether the loan lasts one year or ten. The shorter the actual holding period, the fewer months over which that fee is spread. Borrowers expecting a home sale, refinance, bonus payoff, or business liquidity event should model that expected payoff date. A lower contract rate purchased with a large fee can be a poor trade when the debt disappears before the payment savings recover the initial cost.']},
{heading:'Rate locks and credits can change before closing',text:['Mortgage pricing depends on market rates, lock period, loan characteristics, and lender adjustments. A quote with points today may not be directly comparable with a no-point quote obtained on another day. Request side-by-side options from the same lender at the same time when possible, or compare locked Loan Estimates with equivalent assumptions. This reduces the risk of attributing a market-rate change to the fee structure itself.']},
{heading:'Break-even is a decision threshold, not a guarantee',text:['A 48-month break-even means the cumulative nominal payment savings catch the extra upfront fee around month 48 under the modeled loan schedule. It does not account automatically for investment return on retained cash, tax effects, prepayment changes, or future refinancing opportunities. Still, it is a powerful first screen: if the borrower is highly likely to move in two years, paying points with a four-year break-even deserves skepticism.']},]},
{heading:'Loan Origination Fee Calculator — topic 2',text:['If a fee is deducted from proceeds, the borrower may sign for a $20,000 loan but receive less usable cash. That matters for personal loans and business loans where the borrower needs a specific net amount. To receive a desired amount after a percentage fee, the gross loan may need to be larger. Do not compare offers only by stated principal if one lender withholds a fee before disbursement.']},
{heading:'Loan Origination Fee Calculator — topic 3',text:['For mortgages, discount points and lender credits are closely related to rate pricing. Paying points can buy a lower rate; accepting a higher rate can generate a credit toward closing costs. The break-even period compares the extra upfront cost with monthly payment savings. If $4,000 of additional points saves $80 per month, a simple break-even is 50 months. That calculation should use the actual payment difference between otherwise comparable loans and should consider whether the borrower expects to refinance, sell, or prepay before break-even.']},
{heading:'Loan Origination Fee Calculator — topic 4',text:['APR can help compare financing cost because it incorporates certain finance charges into an annualized rate, but APR is not a perfect prediction of what every borrower will pay. It depends on required disclosures, assumed loan life, and included fees. A borrower who pays off a loan early spreads upfront fees over fewer years, increasing their effective cost. Compare APR, cash to close, monthly payment, and total interest over the expected holding period.']},
{heading:'Loan Origination Fee Calculator — topic 5',text:['Financing the fee avoids some cash at closing but increases the amount on which interest accrues. Paying the fee in cash requires more liquidity but avoids interest on that fee. If the fee is added to a mortgage balance, check loan-to-value implications and program limits. If a personal-loan fee is withheld, make sure the net proceeds still cover the intended use.']},
{heading:'Loan Origination Fee Calculator — topic 6',text:['A no-fee offer is not necessarily cheaper. The lender may recover cost through a higher interest rate. Conversely, a fee-heavy loan is not automatically bad if the rate reduction creates enough savings over a long holding period. The economically correct comparison puts all offers on the same principal, term, and expected payoff date and then measures both upfront and recurring costs.']},
{heading:'Loan Origination Fee Calculator — topic 7',text:['Suppose Loan A charges no origination fee at 7.25%, while Loan B charges 1% at 6.75%. Calculate each required payment using the same loan amount and term. Add the fee to Loan B’s initial cost, then accumulate monthly payment differences until they recover that fee. If the expected loan life is shorter than that point, the lower-fee loan may be better; if much longer, the lower-rate loan may win. Taxes and deductibility, where relevant, require separate analysis.']},
{heading:'Loan Origination Fee Calculator — topic 8',text:['Before closing, reconcile calculator inputs with the lender’s official disclosure. Identify which charges are lender fees, third-party costs, prepaid interest, escrow funding, taxes, or optional services. Calling every closing cost an origination fee overstates lender pricing and can distort comparisons. The calculator should isolate the fee being evaluated and avoid double-counting it elsewhere.']},
]},
'genetic-height-calculator':{title:'Genetic Height Calculator',sections:[
{heading:'Genetic Height Calculator — topic 1',text:['Mid-parental height is a rough screening estimate based on parental stature, not a genetic test and not a promise of adult height. A commonly used clinical approach combines the parents’ heights and applies a sex-related adjustment before averaging. Different references may express the adjustment differently or provide target ranges around the estimate. Because height is polygenic and strongly influenced by development, the result should be interpreted as a central estimate with substantial natural variation.',
{heading:'Target range is more useful than an exact point',text:['Clinical references often interpret mid-parental height with a target range rather than claiming the child will reach one exact number. Normal genetic segregation alone creates meaningful sibling differences. Presenting 174.2 cm as if it were precise to a millimeter gives false confidence. Round sensibly and emphasize the range. The midpoint can help contextualize a growth pattern, while the child’s measured trajectory over time provides more information than the decimal precision of the estimate.',
{heading:'Family history extends beyond two heights',text:['Parental height summarizes important genetic information but does not capture the full family distribution. Grandparents, siblings and other relatives can show whether unusually short or tall stature is common in the family. That history can help a clinician interpret a child’s trajectory, although it does not belong in a simple mid-parental formula. A calculator should therefore present the parental estimate modestly rather than implying two measurements contain the child’s complete genetic growth information.']},
{heading:'Adult height is reached on different schedules',text:['Girls and boys, and individuals within each group, finish linear growth at different ages depending largely on pubertal timing and skeletal maturation. A teenager who is still growing cannot infer remaining centimeters from current age alone. Statements such as everyone stops at 18 are oversimplified. If remaining growth is clinically important, longitudinal measurements and, when indicated, assessment of maturation provide more useful evidence than repeatedly changing the parental-height formula.']},
{heading:'Population reference matters',text:['Height distributions differ across populations and generations because of both genetic background and environmental conditions. A formula calibrated from one reference population may not have identical accuracy everywhere. This is another reason to avoid false precision. The broad purpose of mid-parental height is to place a child’s growth in family context, not to rank families or establish a universal biological target.']},
{heading:'Use the result constructively',text:['For a healthy child, the best use of the estimate is reassurance and context: compare family stature with the child’s ongoing growth record and support normal nutrition, sleep and healthcare. Avoid using the number to pressure a child about sports, appearance or expected adult size. Height is only one physical trait, and a prediction error of several centimeters is entirely plausible even when the formula is applied correctly.']},]},
{heading:'Sex adjustment is formula-specific',text:['Common mid-parental formulas use an adjustment reflecting average adult height differences between males and females in the reference population. Some descriptions add a fixed number to one parent before averaging; equivalent formulations may adjust the parental mean. Users should not mix pieces from different formulas. Use one validated reference consistently, keep units identical, and understand that population averages can shift over generations and across populations.']},
{heading:'Growth velocity adds temporal information',text:['Height percentile says where a child is at one moment; growth velocity says how quickly height is changing. A child who is short but growing steadily along an expected channel can present a different picture from a child who crosses multiple percentile lines downward. Calculating annualized growth requires accurate measurements separated by enough time. Home measurements can be useful for records but should not substitute for standardized clinical measurements when a growth concern exists.']},
{heading:'Nutrition supports potential but does not set a chosen height',text:['Adequate calories, protein, micronutrients, sleep, and general health support normal development. Once nutritional needs are met, consuming extra supplements does not reliably push a healthy child beyond genetic potential. Products marketed as height boosters often overstate evidence. The responsible use of a height calculator is to understand family context, not to prescribe diets, drugs, stretching routines, or hormones based on a desired target.']},
{heading:'When the calculator is the wrong tool',text:['A parental-height estimate cannot evaluate growth hormone deficiency, thyroid disease, celiac disease, chronic systemic illness, skeletal dysplasia, or delayed puberty. It also cannot interpret a sudden stop in growth. If a child’s clinician is concerned about growth velocity, percentile crossing, disproportion, or puberty timing, assessment may include medical history, examination, laboratory work, or bone age. Those questions require individualized care rather than a more complicated online formula.']},]},
{heading:'Genetic Height Calculator — topic 2',text:['Accurate parental measurements matter. Adult height should be measured without shoes, standing upright against a stadiometer or flat wall, with the head positioned consistently. Self-reported heights are often rounded upward. If one parent’s height is guessed by several centimeters, the child estimate moves as well. Convert feet and inches to total inches or centimeters before applying a formula, and convert back only after calculation.']},
{heading:'Genetic Height Calculator — topic 3',text:['Genetics explains a large share of population variation in height, but hundreds or thousands of genetic variants contribute small effects. Nutrition, chronic disease, endocrine conditions, prenatal factors, sleep, and timing of puberty can influence realized growth. Two siblings with the same parents can reach different adult heights because they inherit different combinations of variants and experience different developmental conditions.']},
{heading:'Genetic Height Calculator — topic 4',text:['Growth percentiles answer a different question. A percentile compares a child’s current height with a reference population of the same age and sex. Mid-parental height estimates a family-related adult target. Clinicians may consider whether a child tracks along a percentile channel and whether that pattern is broadly consistent with family height. One percentile reading or one parental-height calculation should not be used alone to diagnose a growth problem.']},
{heading:'Genetic Height Calculator — topic 5',text:['Puberty timing can make short-term comparisons confusing. An early-maturing adolescent may temporarily be much taller than peers and stop growing sooner, while a late maturer may appear shorter for several years and continue growing later. Bone age assessment, when medically indicated, provides information that a simple age-and-parent calculator does not. The calculator cannot determine remaining growth from chronological age alone.']},
{heading:'Genetic Height Calculator — topic 6',text:['Measurement error is common in children. Time of day, posture, hair, footwear, wall markings, and rounding can create apparent changes. Growth velocity requires measurements separated by enough time and taken consistently. Repeated accurate measurements are more informative than repeatedly recalculating adult height after tiny short-term differences.']},
{heading:'Genetic Height Calculator — topic 7',text:['A useful example is a family in which one parent is 180 cm and the other 165 cm. A mid-parental formula combines those values and applies the formula’s sex adjustment to estimate a central adult target. The clinically relevant interpretation is usually a range around that target, not a single exact centimeter. A child finishing several centimeters above or below the midpoint can still be entirely consistent with normal family variation.']},
{heading:'Genetic Height Calculator — topic 8',text:['Parents should avoid using height predictions to justify supplements, restrictive diets, hormones, or unproven interventions. Adequate nutrition and treatment of genuine medical conditions support normal growth, but there is no safe calculator-based method to force a healthy child to a chosen height. Concerns about unusually slow growth, crossing percentile lines, delayed or early puberty, or other symptoms belong with a pediatric clinician who can evaluate the whole growth history.']},
]},
'home-equity-vs-personal-loan':{title:'Home Equity vs Personal Loan',sections:[
{heading:'Home Equity vs Personal Loan — topic 1',text:['A home-equity loan is secured by the borrower’s home, while a personal loan is commonly unsecured. Collateral often allows a home-equity loan to offer a lower interest rate or larger amount, but it also raises the stakes of default because the home secures repayment. A personal loan can close faster and avoids placing an additional lien on the property, but pricing may be higher because the lender has less collateral protection.',
{heading:'Fixed home-equity loan versus HELOC',text:['A lump-sum home-equity loan commonly has a fixed payment schedule, while a HELOC is a revolving line that often has a variable rate and separate draw and repayment periods. Comparing a personal loan with a HELOC requires assumptions about when funds are drawn and how quickly principal is repaid. A variable HELOC can begin cheaper and later become more expensive if benchmark rates rise. Do not label every home-equity product as one fixed-rate alternative.']},
{heading:'Closing costs change with loan size',text:['Secured-loan fees are especially important on smaller balances. A $2,000 closing-cost package is only 1% of a $200,000 loan but 10% of a $20,000 loan. That can make an unsecured personal loan economically competitive despite a higher APR when the borrowing need is modest or short-lived. Convert every fixed fee into dollars and evaluate it over the expected loan life rather than focusing on rate alone.']},
{heading:'CLTV protects the lender, not the household budget',text:['A lender may permit a combined loan-to-value that leaves substantial borrowing capacity, but that does not mean using all available equity is prudent. Home value can fall, and a high CLTV reduces flexibility to refinance or sell without bringing cash to closing. Preserve an equity cushion appropriate to the household’s risk tolerance. Borrowing capacity is a ceiling established by underwriting, not a recommended debt target.']},
{heading:'Debt consolidation can shift rather than solve risk',text:['Using a lower-rate home-equity loan to repay credit cards can reduce interest, but the benefit depends on keeping the cards from rebuilding balances. Otherwise the household can end up with both secured home debt and new revolving debt. Pair consolidation with a spending plan, automatic repayment, and an emergency reserve. The calculator should show interest savings under the assumption that old balances stay paid; the household must make that assumption true.']},
{heading:'Compare flexibility and prepayment rules',text:['Personal loans and home-equity products can differ in prepayment penalties, minimum draws, annual fees, recapture of waived closing costs, and ability to reborrow. A HELOC may provide reusable liquidity during the draw period, while a closed-end loan does not. Flexibility has value for a renovation with uncertain invoices, but it can also encourage persistent borrowing. Read the contract features beside the numerical comparison.']},]},
{heading:'Home Equity vs Personal Loan — topic 2',text:['Compare equal borrowing needs and equal horizons. If one loan has a longer term, its monthly payment may look easier while total interest is higher. Calculate payment, total scheduled interest, origination or closing fees, and the balance remaining at the date you realistically expect to repay or refinance. For home-equity borrowing, include appraisal, recording, title, annual fees, or early-closure charges where applicable. For personal loans, include any origination fee withheld from proceeds.']},
{heading:'Home Equity vs Personal Loan — topic 3',text:['Available home equity is not the same as the amount a lender will advance. Combined loan-to-value, or CLTV, compares the first mortgage plus proposed home-equity debt with property value. Lenders set their own CLTV limits and also evaluate income, credit, and property eligibility. An optimistic home value can overstate available borrowing, so use a defensible current value and leave room for appraisal differences.']},
{heading:'Home Equity vs Personal Loan — topic 4',text:['Tax treatment should not be assumed. Under US federal rules, deductibility of home-equity interest has depended on how proceeds are used and on other requirements; rules can change by tax year. Borrowing against a home to pay personal expenses does not automatically make the interest deductible. A personal-loan interest deduction is also uncommon for personal consumption, though business or investment uses can have separate rules. Model taxes only when the facts support them.']},
{heading:'Home Equity vs Personal Loan — topic 5',text:['A $50,000 home-equity loan at a lower APR may save interest relative to a personal loan, but the comparison changes if the secured loan requires several thousand dollars of closing costs and the borrower repays it quickly. Break-even analysis divides the extra upfront cost by monthly interest or payment savings, then checks whether the loan is likely to remain outstanding long enough.']},
{heading:'Home Equity vs Personal Loan — topic 6',text:['Risk tolerance belongs beside the arithmetic. Using home equity to consolidate unsecured credit-card debt can lower the rate, but it converts debt that was not secured by the home into debt that is. If spending behavior is not fixed, balances can rebuild while the home remains pledged. A lower rate is valuable only when the repayment plan is sustainable.']},
{heading:'Home Equity vs Personal Loan — topic 7',text:['Speed and certainty also differ. Personal loans can sometimes fund quickly with a simpler process. Home-equity loans may require valuation, lien checks, disclosures, and a longer closing process. For an urgent expense, timing can have value. For a planned renovation, waiting for cheaper secured financing may be reasonable. The calculator should quantify cost while the borrower separately considers execution risk.']},
{heading:'Home Equity vs Personal Loan — topic 8',text:['Do not compare advertised APRs without matching credit assumptions, fees, term, and loan type. Fixed home-equity loans differ from variable-rate HELOCs, and a personal loan with a low headline rate may charge a large origination fee. Obtain actual quotes and compare net proceeds, payment schedule, total cost over the expected life, and collateral consequences.']},
]},
'merit-raise-vs-job-change-calculator':{title:'Merit Raise vs Job Change Calculator',sections:[
{heading:'Merit Raise vs Job Change Calculator — topic 1',text:['Staying and switching create two different salary paths. The stay path begins with current compensation and applies expected merit increases. The switch path starts with the new offer, may include a signing bonus, and then grows from a different salary base. Because percentage raises compound, an early salary jump can affect several future years even if later raise rates are identical. Compare cumulative compensation over a realistic tenure rather than only the first paycheck.',
{heading:'Promotion probability belongs in the stay case',text:['Employees sometimes compare a guaranteed external offer with an internal path that assumes a promotion will definitely happen. Separate the current-role merit raise from a promotion scenario and assign the latter only if there is credible evidence about timing and compensation. A verbal possibility is not the same as an approved promotion. Running both cases shows how much the decision depends on internal advancement rather than hiding that uncertainty inside one growth percentage.',
{heading:'Counteroffers create a third path',text:['A current employer may respond to resignation with a counteroffer. Model it as a separate scenario rather than silently replacing the stay salary. Ask whether the counter changes base pay only or also title, scope and promotion path, and whether the reasons that prompted the job search remain. A counteroffer can be financially strong yet still fail to solve workload, management or career issues. The calculator can compare dollars, while the employee evaluates trust and long-term fit.']},]},
{heading:'Vesting dates create departure cliffs',text:['Unvested RSUs, options, retention bonuses, and employer-match vesting can create sharp dates where leaving one week later is worth materially more. Map those dates before choosing a start date. A new employer may provide a make-whole award, but its vesting or clawback can create a new cliff. Compare compensation actually expected to vest during the analysis horizon, not the headline value of grants that could be forfeited.']},
{heading:'Benefits can move recurring value',text:['A $12,000 salary increase can be partly offset by higher family health premiums, a weaker retirement match, less paid leave, or a costly commute. Conversely, a modest salary increase can be attractive when the new employer covers more insurance or offers a strong match. Annualize the large recurring differences and keep them in a separate benefits line. This makes it clear whether the advantage comes from cash salary or from the broader employment package.']},
{heading:'Risk discount should be transparent',text:['If the calculator discounts the switch path for uncertainty, show the undiscounted dollars too. A 10% risk haircut is not an observed market price; it is a judgment about job stability, probation, company health, or fit. Two users can reasonably choose different discounts. Rather than arguing over one correct percentage, test several values and identify the level at which the financial conclusion changes.']},
{heading:'Time horizon should match likely tenure',text:['A ten-year projection can exaggerate tiny differences in assumed raise rates when neither job is likely to last ten years. Use a horizon that reflects realistic tenure, then optionally extend it to understand compounding. If the main decision is whether to accept a new role for the next two to four years, that period deserves the most weight. Long projections are useful for sensitivity, not as a claim that either employer will follow the same compensation policy indefinitely.']},]},
{heading:'Merit Raise vs Job Change Calculator — topic 2',text:['A job-change premium should be measured against what you would actually earn by staying. If an annual merit review is imminent, include the expected raise in the stay baseline. If a promotion is realistically likely, model it separately rather than assuming ordinary merit growth forever. The same discipline applies to the new job: do not assume unusually large annual increases simply because the initial offer is strong.']},
{heading:'Merit Raise vs Job Change Calculator — topic 3',text:['Variable compensation can reverse a salary-only conclusion. Include expected bonus, commissions, equity vesting, retirement match, and any compensation forfeited by leaving. A signing bonus may be designed to replace an annual bonus or unvested award left behind. Check clawback language: some signing payments must be repaid if employment ends within a stated period.']},
{heading:'Merit Raise vs Job Change Calculator — topic 4',text:['Switching has one-time costs and risks. Relocation, commuting, a waiting period for benefits, different health premiums, loss of accrued leave, and retirement-plan vesting can reduce the economic gain. Probationary periods or an uncertain company outlook can add risk that is difficult to price. A calculator may apply a probability or risk discount, but that percentage is subjective; show the undiscounted path as well so the assumption is visible.']},
{heading:'Merit Raise vs Job Change Calculator — topic 5',text:['Career capital matters even when it is not immediately cash. A role with better scope, mentorship, technology, leadership exposure, or a stronger title can improve later earning power. Conversely, a higher-paying role with limited learning or unsustainable hours can reduce long-term options. Keep these qualitative factors outside the dollar total instead of inventing precise monetary values for them.']},
{heading:'Merit Raise vs Job Change Calculator — topic 6',text:['Suppose staying pays $100,000 with 4% annual merit increases, while a new job offers $115,000 with 3% annual raises. The new job begins $15,000 ahead, and subsequent raises build on the higher base. Over several years the cumulative gap can be much larger than $15,000. If switching forfeits a $10,000 bonus and adds $5,000 of annual commuting cost, subtract those amounts before calling the move financially superior.']},
{heading:'Merit Raise vs Job Change Calculator — topic 7',text:['Taxes affect take-home pay but usually do not erase the value of higher gross income. A common mistake is believing that entering a higher tax bracket causes all income to be taxed at the higher marginal rate. Progressive brackets apply higher rates only to income within those bands. For decision-making, compare after-tax cash if needed, but do not reject a raise based on bracket misunderstanding.']},
{heading:'Merit Raise vs Job Change Calculator — topic 8',text:['Run break-even analysis. Add the one-time costs of switching and divide by the recurring monthly or annual compensation advantage to estimate how long it takes to recover them. If you may leave the new role before that point, the move deserves more scrutiny. If the new role has both a large immediate increase and better long-term growth, the break-even may be very short.']},
{heading:'Merit Raise vs Job Change Calculator — topic 9',text:['Avoid treating a recruiter’s target bonus as guaranteed, valuing unvested equity at face value, or forgetting the next scheduled raise at your current employer. Do not compare a remote current job with an office-based offer without commuting cost and time. The calculator is strongest when each path reflects what you would realistically receive and when uncertainty is shown explicitly.']},
]},
'rental-property-depreciation-calculator':{title:'Rental Property Depreciation Calculator',sections:[
{heading:'Rental Property Depreciation Calculator — topic 1',text:['US rental-property depreciation generally allocates the depreciable basis of a building over a tax recovery period using rules that depend on property type and placed-in-service timing. Land is not depreciable, so a purchase price must be allocated between land and building. For residential rental real estate, the commonly cited recovery period is 27.5 years under MACRS; nonresidential real property generally uses a longer period such as 39 years under current rules. The exact convention and tables matter, especially in the first and final years.',
{heading:'Land allocation deserves evidence',text:['Because land is not depreciable, an aggressive low land allocation increases annual building depreciation. The allocation should be supportable rather than chosen to maximize a deduction. County assessments can provide one reference but may not equal fair market allocation; appraisals or other valuation methods may be appropriate. Keep the source with tax records. A calculator can show how allocation changes depreciation, but it cannot establish the legally correct land value.',
{heading:'Furniture and appliances may follow different schedules',text:['A furnished rental can include appliances, furniture, carpeting, land improvements and other assets that are not necessarily depreciated over the building’s 27.5- or 39-year life. Their classification, recovery periods and eligibility for accelerated deductions depend on current tax law and facts. Lumping every acquisition dollar into building basis can understate or mis-time depreciation. A basic building calculator should therefore be labeled as a building estimate, not a complete asset-by-asset depreciation schedule.']},
{heading:'Improvements placed in service later have their own start dates',text:['A new roof installed three years after the rental begins does not retroactively increase the original building’s depreciation from day one. Capitalized improvements generally create additional basis with their own placed-in-service timing and applicable recovery treatment. Keep an improvement ledger with date, cost, description and tax classification. This makes later depreciation and adjusted-basis calculations much easier, especially when the property is sold.']},
{heading:'Partial dispositions can complicate basis',text:['Replacing a major building component can sometimes raise questions about whether the retired component has a remaining basis that may be disposed of under applicable regulations. This is beyond a simple annual depreciation calculator but can materially affect tax reporting for large renovations. Owners making major replacements should not assume the only tax effect is adding the new cost to basis; professional review may identify additional treatment.']},
{heading:'Depreciation affects investment metrics differently',text:['Depreciation changes taxable income but does not directly change property NOI in many real-estate performance analyses because it is noncash and below the operating line. When comparing cash-on-cash return with after-tax return, keep those layers distinct. A property can have strong operating cash flow and a tax loss because of depreciation, or weak cash flow despite a large deduction. The calculator’s depreciation output should feed the tax model, not replace the operating model.']},]},
{heading:'Cost segregation changes timing, not total economics by magic',text:['A cost-segregation study may identify components with shorter recovery periods than the building, accelerating deductions. That can improve present-value tax benefits, particularly when bonus-depreciation rules apply, but it also creates additional records and can affect disposition calculations. A simple 27.5-year or 39-year building calculator does not model those component classes. Investors considering cost segregation should compare the after-tax timing benefit with study cost and their ability to use the deductions.']},
{heading:'Personal-to-rental conversions need special basis rules',text:['A former personal residence converted to rental use does not always begin depreciation from the original purchase price. Tax basis for depreciation can depend on adjusted basis and fair market value at conversion under applicable rules. This can matter after a property declines in value before becoming a rental. Do not enter today’s market value or original cost automatically when the property has a prior personal-use history.']},
{heading:'Vacancy does not automatically stop depreciation',text:['A rental temporarily vacant while being held out and available for rent can have different treatment from property withdrawn from service or converted to personal use. The key concept is whether it remains placed in service for income-producing use under tax rules. A calculator that asks only purchase and property type cannot decide that factual question. Maintain records of listings, repairs, and use when periods of vacancy or conversion occur.']},
{heading:'Tax savings should use the usable deduction',text:['Multiplying depreciation by a marginal rate estimates potential tax reduction only if the deduction is currently usable against income taxed at that rate. Passive-activity limitations can suspend losses for some owners. Suspended losses may become usable later under applicable rules, changing timing and present value. Distinguish annual depreciation generated from depreciation that actually reduces current-year tax. That prevents the calculator from overstating immediate cash benefit.']},]},
{heading:'Rental Property Depreciation Calculator — topic 2',text:['Depreciable basis usually starts with the portion of acquisition cost allocated to the building, adjusted for certain capitalized acquisition costs and later capital improvements. It is not simply the property’s current market value. If a $500,000 purchase is reasonably allocated 20% to land and 80% to building before other basis adjustments, the initial building portion is $400,000. Documentation for the allocation should be defensible; tax assessments, appraisals, and professional advice may be relevant.']},
{heading:'Rental Property Depreciation Calculator — topic 3',text:['Placed-in-service date is different from purchase date. Depreciation begins when the property is ready and available for its income-producing use, not necessarily when the deed changes hands or when the first tenant pays rent. A property undergoing a major renovation for months after purchase may have a later placed-in-service date. The applicable convention can make first-year depreciation a partial-year amount rather than a simple annual basis divided by 27.5 or 39.']},
{heading:'Rental Property Depreciation Calculator — topic 4',text:['Repairs and improvements are not interchangeable. Ordinary repairs may be currently deductible when tax rules allow, while improvements that better, restore, or adapt property generally must be capitalized and depreciated. Replacing a broken doorknob is different from replacing an entire roof. Separate assets can also have different recovery periods. A basic calculator that applies one building life cannot perform a full cost-segregation study.']},
{heading:'Rental Property Depreciation Calculator — topic 5',text:['Depreciation is a noncash deduction: it can reduce taxable rental income without requiring an equivalent cash payment in that year. That does not mean the deduction is free money. Passive-activity rules, at-risk rules, income limitations, and the taxpayer’s broader situation can limit when losses are usable. A calculator estimating tax savings as depreciation times a marginal rate is a simplification unless it models those restrictions.']},
{heading:'Rental Property Depreciation Calculator — topic 6',text:['Sale creates another layer. Depreciation allowed or allowable generally reduces adjusted basis, which can increase taxable gain. US tax law can subject the depreciation-related portion of gain to special treatment often described as unrecaptured Section 1250 gain, with rules more nuanced than simply repaying every deduction at one fixed rate. Do not evaluate a rental solely on annual tax savings without considering exit taxation.']},
{heading:'Rental Property Depreciation Calculator — topic 7',text:['Suppose a residential rental has a $330,000 depreciable building basis. A rough full-year straight-line intuition is $12,000 per year over 27.5 years, but the actual first-year MACRS amount depends on the placed-in-service month and convention. That difference is why an educational calculator should identify whether it is producing a simplified annual estimate or a tax-return-ready schedule.']},
{heading:'Rental Property Depreciation Calculator — topic 8',text:['Refinancing does not reset depreciation basis merely because a new loan is larger or the property appraises higher. Depreciation follows tax basis, not mortgage balance. Likewise, market appreciation does not create additional depreciable basis. Capital improvements can add basis, while casualty events, dispositions, or conversions between personal and rental use can require special handling.']},
{heading:'Rental Property Depreciation Calculator — topic 9',text:['Keep closing statements, allocation support, improvement invoices, prior depreciation schedules, and placed-in-service records for the life of the property and through disposition. A missing schedule years later can make adjusted-basis calculations difficult. For filing, reconcile calculator estimates with tax software or a qualified professional, particularly when there are multiple assets, partial business use, exchanges, inherited property, or prior-year errors.']},
]},
'roth-vs-traditional-401k-calculator':{title:'Roth vs Traditional 401(k) Calculator',sections:[
{heading:'Roth vs Traditional 401(k) Calculator — topic 1',text:['Traditional 401(k) contributions generally reduce current taxable income for federal income-tax purposes, while qualified Roth 401(k) withdrawals are designed to be tax-free after applicable requirements are met. The central comparison is therefore the tax rate avoided on the contribution versus the tax rate that would apply to the traditional withdrawal later. If those rates are identical and all tax savings are invested equivalently, the two can be economically similar before other rule differences.',
{heading:'Same contribution versus same take-home cost',text:['If both accounts receive $10,000, Roth requires more current after-tax cash because the traditional contribution creates a tax deduction. A same-take-home-cost comparison would invest less into Roth or invest the traditional tax savings separately. State clearly which framework the calculator uses. Many online comparisons accidentally favor one side by ignoring the tax savings or by assuming those savings are invested without showing them.',
{heading:'Contribution room can make Roth effectively larger',text:['When an employee is already contributing the legal maximum, a maximum Roth contribution places more after-tax economic value inside the tax-advantaged account than the same nominal traditional contribution because future qualified Roth withdrawals do not carry the same income-tax liability. A traditional saver could invest the current tax savings in a taxable account, but contribution limits prevent placing that extra amount into the same 401(k). This can strengthen Roth for high savers, though current tax rates still matter.']},
{heading:'Cash-flow constraints can favor traditional today',text:['Traditional contributions can reduce current income-tax withholding and make a given retirement contribution easier to afford. A worker who cannot sustain the same nominal Roth amount should compare equal take-home cost rather than forcing an unrealistic contribution. The best theoretical tax treatment is not useful if it causes high-interest debt or an inadequate emergency reserve. Retirement tax optimization sits inside the broader household cash-flow plan.']},]},
{heading:'Future effective rate can differ from future marginal rate',text:['A traditional withdrawal may be spread across lower brackets in retirement even if the retiree’s highest marginal bracket equals today’s. If retirement income first fills the standard deduction and lower brackets, the average tax rate on a block of withdrawals can be below the top marginal rate. On the other hand, pensions, Social Security, and other income may already fill those lower bands. Model the incremental tax on the withdrawal rather than applying one rate blindly to every retirement dollar.']},
{heading:'Roth contributions can be valuable in low-income years',text:['Early-career workers, sabbatical years, or temporary income dips can create unusually low marginal tax rates. Paying tax now through Roth contributions can be attractive when the alternative traditional deduction is worth little. High-income peak-earning years can favor traditional contributions for the opposite reason. This suggests contribution type can change over a career rather than being a once-for-life identity choice.']},
{heading:'Required distributions and estate goals can matter',text:['Pre-tax retirement accounts can create future required distributions under applicable law, increasing taxable income even when the retiree does not need the cash. Roth account rules have changed over time and can provide different planning flexibility. Beneficiary distribution rules also matter for estate planning. These features are secondary to the basic tax-rate comparison for many workers but can be meaningful for large balances.']},
{heading:'Tax uncertainty supports diversification',text:['No calculator can know federal and state tax law decades ahead. Holding both pre-tax and Roth assets reduces dependence on one forecast. If the modeled advantage is small, a split contribution can be reasonable because it preserves future withdrawal choices. If the advantage is large under a wide range of plausible future rates, the model provides a stronger signal. Focus on the break-even rate and sensitivity range rather than one precise retirement-tax assumption.']},]},
{heading:'Roth vs Traditional 401(k) Calculator — topic 2',text:['A fair model must account for the current tax savings from a traditional contribution. If a worker contributes $10,000 and avoids 24% federal marginal income tax, the immediate federal tax difference is roughly $2,400 before state effects and other interactions. Comparing $10,000 traditional with $10,000 Roth while simply spending the traditional tax savings gives Roth an implicit extra cash commitment. Decide whether the comparison holds contribution dollars constant or holds take-home cost constant.']},
{heading:'Roth vs Traditional 401(k) Calculator — topic 3',text:['Marginal tax rate matters more than average tax rate for the deduction decision because the contribution generally reduces dollars at the margin. Retirement withdrawals can fill several tax brackets, so using today’s top marginal rate for every future dollar may overstate traditional tax. Other retirement income—Social Security, pensions, required distributions, investment income, and a spouse’s income—can influence the bracket occupied by 401(k) withdrawals.']},
{heading:'Roth vs Traditional 401(k) Calculator — topic 4',text:['Employer matching should be modeled according to the plan’s actual rules and tax treatment. A match increases retirement wealth regardless of whether the employee chooses Roth or traditional contributions, but the account type receiving employer contributions can differ under current plan rules. Do not assume the match has the same tax character as the employee contribution without checking the plan.']},
{heading:'Roth vs Traditional 401(k) Calculator — topic 5',text:['State taxes can affect the comparison if the worker contributes in one state and retires in another. A high-tax working state and low-tax retirement state can favor the current traditional deduction, while the reverse can strengthen Roth. State treatment of retirement income varies, so long-range projections should use scenarios rather than pretending residence decades from now is certain.']},
{heading:'Roth vs Traditional 401(k) Calculator — topic 6',text:['Roth can provide tax diversification. A retiree with both pre-tax and Roth assets may choose which account to draw from in a given year, potentially managing taxable income around brackets, Medicare-related thresholds, or other tax interactions. Traditional balances can create future taxable distributions; Roth treatment and required-distribution rules have also evolved legislatively. Use current law for current planning and recognize that future rules can change.']},
{heading:'Roth vs Traditional 401(k) Calculator — topic 7',text:['Suppose a worker is in a 32% marginal bracket today and expects withdrawals to fall largely in a 22% bracket later. Traditional contributions have an apparent rate advantage if the tax savings are preserved. If the worker is in a 12% bracket today but expects substantially higher taxable retirement income, Roth can be attractive. The calculator should show the break-even future tax rate at which the modeled outcomes are equal.']},
{heading:'Roth vs Traditional 401(k) Calculator — topic 8',text:['Contribution limits apply across employee elective deferrals according to current law and can change annually. Catch-up rules can apply at certain ages and may have special Roth requirements for some higher earners under newer legislation. A calculator labeled for 2026 should verify the applicable statutory limits rather than reusing older numbers. Plan-specific payroll limits can also matter.']},
{heading:'Roth vs Traditional 401(k) Calculator — topic 9',text:['Do not choose Roth solely because tax-free sounds better or traditional solely because a deduction is available today. Compare the tax rates, treatment of current savings, investment horizon, expected retirement income, state situation, and need for tax diversification. When the answer is close, splitting contributions can reduce the risk of making one large bet on future tax policy.']},
]},
'wash-sale-calculator':{title:'Wash Sale Calculator',sections:[
{heading:'Wash Sale Calculator — topic 1',text:['The US wash-sale rule can disallow a tax loss when stock or securities are sold at a loss and substantially identical stock or securities are acquired within the statutory window surrounding the sale. The commonly discussed window covers 30 days before the sale, the sale date, and 30 days after, effectively a 61-day period to monitor. The rule is designed to prevent a taxpayer from claiming a loss while maintaining essentially the same investment position.']},
{heading:'Wash Sale Calculator — topic 2',text:['When a wash sale occurs in a taxable account, the disallowed loss is generally added to the basis of the replacement shares, and the holding period can carry over. That usually defers the loss rather than destroying it. If 100 shares are sold for a $1,000 loss and 100 substantially identical replacement shares trigger the rule, the $1,000 is added to the replacement lot’s basis. A later sale can then reflect that higher basis.']},
{heading:'Wash Sale Calculator — topic 3',text:['Partial replacements create partial wash sales. If 100 shares are sold at a loss but only 40 replacement shares are acquired in the window, the loss associated with those 40 shares can be disallowed while the remaining portion may remain recognized, subject to lot matching rules. A useful calculator therefore needs quantities and tax lots, not just two dates.']},
{heading:'Wash Sale Calculator — topic 4',text:['Purchases before the loss sale matter too. Investors sometimes watch only the 30 days after selling, but buying substantially identical shares during the preceding 30 days can also trigger the rule if the relevant requirements are met and the replacement shares remain held. Automatic dividend reinvestment is an easy source of accidental replacement purchases because a small recurring buy can occur inside the window.']},
{heading:'Wash Sale Calculator — topic 5',text:['Retirement accounts require special caution. If a loss sale in a taxable account is followed by acquisition of substantially identical property in an IRA or Roth IRA, IRS guidance can produce a particularly unfavorable result because the disallowed loss may not simply increase taxable-account basis in the usual way. Taxpayers using loss harvesting across multiple accounts should coordinate trades rather than reviewing each brokerage account in isolation.']},
{heading:'Wash Sale Calculator — topic 6',text:['The phrase substantially identical is facts-and-circumstances based and is not defined by a simple percentage-overlap test for every security. Buying the exact same stock is the clearest case. Different broad-market funds tracking different indexes may be less likely to be substantially identical, but superficial ticker differences do not guarantee safety. Options, convertible securities, and other instruments can complicate the analysis. A calculator can flag dates and obvious replacements but cannot conclusively classify every pair of investments.']},
{heading:'Wash Sale Calculator — topic 7',text:['Tax-loss harvesting strategies often use a replacement investment that maintains desired market exposure without being substantially identical, then reconsider the original position after the wash window. That creates tracking difference: the substitute can perform differently during the waiting period. The tax benefit should be weighed against transaction costs, spreads, portfolio drift, and the possibility that the replacement rises or falls differently.']},
{heading:'Wash Sale Calculator — topic 8',text:['Broker reporting does not eliminate the taxpayer’s responsibility. A broker may identify wash sales within the accounts and securities it can see, but purchases at another brokerage, a spouse’s account in relevant circumstances, or certain retirement accounts may not be captured on one Form 1099-B. Maintain a cross-account trade record when harvesting losses.']},
{heading:'Wash Sale Calculator — topic 9',text:['Do not confuse a wash sale with a prohibited trade. The purchase itself is generally not banned; the rule changes the tax treatment of the loss. Also do not apply wash-sale logic automatically to every asset category without checking current law. Legislative proposals and rules for securities, cryptocurrency, and other property can differ by tax year. Use the calculator as a screening tool and verify complex cases before filing.']},
]},
'family-budget-planner-calculator':{title:'Family Budget Planner',sections:[
{heading:'Family Budget Planner — topic 1',text:['A family budget begins with reliable monthly take-home income, not gross salary. Include regular wages after payroll deductions and a conservative average for variable income. Bonuses, commissions, freelance work, support payments, or seasonal income should not be treated as guaranteed if they fluctuate. Households with irregular income can build the core budget around a lower baseline and direct excess months toward sinking funds, debt reduction, or savings.',
{heading:'Housing deserves a full-cost line',text:['For homeowners, housing is mortgage principal and interest plus property tax, homeowners insurance, HOA dues, maintenance, and sometimes utilities that renters may have bundled. For renters, include rent, renter insurance, parking, and required fees. A budget that includes only the headline rent or mortgage understates the household’s largest category. Maintenance can be handled through a monthly reserve even though actual repairs are irregular.',
{heading:'Separate fixed, variable and discretionary costs',text:['Fixed bills such as rent are predictable, variable necessities such as groceries move with usage, and discretionary spending can often be changed quickly. Labeling these types helps when the budget needs adjustment. A $500 monthly shortfall cannot always be solved immediately by changing a fixed lease, but it may be addressed through several variable categories while a longer-term housing or income decision is planned. The classification makes the budget operational rather than merely descriptive.']},]},
{heading:'Childcare can dominate the needs percentage',text:['Daycare, after-school care, camps, diapers, school meals, tuition, and activity costs can make a family budget look far from a generic 50/30/20 split. That does not automatically mean the household is irresponsible. Separate temporary life-stage costs from permanent lifestyle costs and project when they may change. A five-year childcare burden can justify a different savings pace than a permanent housing overcommitment.']},
{heading:'Use a true monthly average for groceries and utilities',text:['Weekly expenses do not convert to monthly by multiplying by four because a year has 52 weeks, not 48. A better monthly conversion is weekly amount times 52 divided by 12. Utilities can be averaged across a full year to capture seasonal heating or cooling. These small conversion details make the budget more realistic and reduce the repeated surprise of five-week months or seasonal bills.']},
{heading:'Plan for replacement cycles',text:['Cars, appliances, phones, computers, furniture, and home systems eventually need replacement. Treating each replacement as an emergency guarantees periodic budget shocks. Estimate a useful life and save gradually where practical. The exact schedule is uncertain, but a replacement reserve turns predictable wear into planned spending. This is especially valuable for families with multiple vehicles or an older home.']},
{heading:'Budget meetings should focus on decisions',text:['A household budget works better when review is short and action-oriented. Compare actual spending with plan, identify the two or three largest variances, update upcoming irregular expenses, and assign the next month’s surplus. Avoid turning every small purchase into a moral argument. The calculator provides categories and targets; the family process determines whether those targets translate into behavior.']},]},
{heading:'Family Budget Planner — topic 2',text:['The 50/30/20 framework divides after-tax income into needs, wants, and savings or debt goals, but it is a benchmark rather than a law. Housing, childcare, healthcare, transportation, and insurance can push needs above 50% in expensive regions or certain life stages. The useful output is the gap between current spending and the chosen target, not a judgment that every family should fit identical percentages.']},
{heading:'Family Budget Planner — topic 3',text:['Classify expenses consistently. Rent or mortgage, basic utilities, groceries, required insurance, minimum debt payments, and necessary transportation usually belong with needs. Dining out, premium subscriptions, discretionary shopping, and entertainment are wants. Savings can include emergency-fund contributions, retirement investing beyond payroll amounts already removed from take-home pay, education goals, and extra debt principal. Ambiguous categories should be handled the same way month to month so trends remain comparable.']},
{heading:'Family Budget Planner — topic 4',text:['Irregular expenses are where many monthly budgets fail. Annual insurance premiums, vehicle repairs, school costs, gifts, travel, medical deductibles, home maintenance, and holidays may not appear every month but are still real. Convert expected annual costs into monthly sinking-fund contributions. A $1,200 annual expense is economically $100 per month even if the bill arrives once.']},
{heading:'Family Budget Planner — topic 5',text:['Emergency savings is different from a sinking fund. A sinking fund is for a known future expense; an emergency fund is for genuinely unexpected disruptions such as job loss or urgent repairs. Families with unstable income, a single earner, high deductibles, or older homes may prefer a larger reserve than a household with multiple stable incomes and strong insurance. The calculator can show monthly capacity, while the target should reflect household risk.']},
{heading:'Family Budget Planner — topic 6',text:['Debt strategy should separate required minimums from accelerated payoff. Minimum payments are part of the current obligation. Extra principal is a financial goal that competes with investing and cash reserves. High-interest revolving debt often deserves priority, but a household should avoid sending every available dollar to debt if that leaves no buffer and forces new borrowing after the next unexpected expense.']},
{heading:'Family Budget Planner — topic 7',text:['A budget should also reconcile payroll deductions. If retirement contributions, health premiums, HSA funding, or commuter benefits are already deducted before the take-home amount entered, do not subtract them again as expenses. Conversely, if the calculator starts from gross income, those deductions must be modeled explicitly. Double-counting payroll items can make a healthy budget look artificially negative.']},
{heading:'Family Budget Planner — topic 8',text:['Use the monthly surplus intentionally. A $700 surplus that simply remains unassigned often disappears into variable spending. Give it jobs: emergency savings, a car-repair fund, retirement, education, vacation, or extra debt payments. If the budget is negative, rank changes by size and feasibility. Renegotiating housing is difficult but powerful; trimming many tiny subscriptions may be easy but insufficient.']},
{heading:'Family Budget Planner — topic 9',text:['Review actual transactions against the plan. A budget built from guesses can be wrong even when the arithmetic is perfect. Compare one to three months of bank and card activity, identify forgotten recurring charges, and update variable categories. The goal is a plan that reflects real behavior closely enough to guide decisions, not a spreadsheet that balances only because spending was underestimated.']},
]},
'tax-bracket-optimizer':{title:'Tax Bracket Optimizer',sections:[
{heading:'Tax Bracket Optimizer — topic 1',text:['US federal income-tax brackets are marginal. Entering a higher bracket does not cause all taxable income to be taxed at the higher rate; only the dollars within that bracket are taxed at that rate. This is the foundation of bracket planning. A taxpayer with taxable income extending into a 24% bracket still has lower portions taxed at the lower rates applicable to those bands. Average tax rate and marginal tax rate therefore answer different questions.',
{heading:'Roth conversions use bracket space deliberately',text:['A Roth conversion moves pre-tax retirement money into a Roth account and generally creates taxable income in the conversion year under applicable rules. The amount can be chosen to fill part of a target bracket, but the conversion can also affect credits, Medicare premiums in later measurement periods, capital-gain rates, and other thresholds. The simple bracket-room number is therefore a starting point. Model the full return impact before converting a large amount.',
{heading:'Marginal rate is useful for evaluating one more dollar',text:['When deciding whether to realize another dollar of ordinary income or claim another deductible dollar, the marginal rate describes the immediate federal bracket effect more directly than the average rate. But the true effective marginal rate can differ when that dollar also changes a credit, deduction, subsidy or preferential-rate threshold. Use the statutory bracket as the first layer, then identify other income-linked provisions that are material for the household.']},]},
{heading:'Business owners have timing levers with constraints',text:['Self-employed taxpayers may have legitimate control over invoicing, deductible purchases, retirement-plan contributions, or entity decisions, but tax accounting methods and business-purpose rules constrain timing. Buying something unnecessary merely for a deduction destroys more cash than the tax saved. Evaluate after-tax economics first. A bracket optimizer should never be read as permission to manufacture deductions or defer income contrary to accounting and tax rules.']},
{heading:'Withholding is not the same as tax liability',text:['A paycheck may withhold at a rate that differs from the taxpayer’s final marginal bracket. Refunds and balances due reflect prepayments versus actual tax, not whether income was taxed correctly. When optimizing brackets, use projected tax liability and taxable income rather than the withholding percentage shown on one paystub. Adjust withholding separately if needed to meet payment requirements and cash-flow preferences.']},
{heading:'Filing status changes thresholds',text:['Single, married filing jointly, married filing separately, and head-of-household statuses have different bracket and deduction structures. A calculator result is invalid if the wrong status is selected. Marriage can create bonuses or penalties depending on the spouses’ incomes and the provisions involved. For a household decision, model the status legally available for the tax year rather than selecting the threshold that produces the preferred answer.']},
{heading:'Tax planning spans calendar boundaries',text:['Accelerating a deduction into December or deferring income into January can shift taxable income between years, but the move only helps when the rate difference and other effects justify it. If next year’s marginal rate will be higher, deferral can backfire. Compare at least two years when timing is controllable. The goal is not to minimize this year’s tax at any cost; it is to improve after-tax wealth across the relevant period.']},]},
{heading:'Tax Bracket Optimizer — topic 2',text:['Optimization starts with taxable income, not gross salary. Adjustments, deductions, filing status, and other items separate gross income from the amount exposed to the ordinary brackets. A calculator that asks for income and deductions is approximating that path. For an actual return, capital gains, qualified dividends, self-employment tax, credits, alternative minimum tax, and other provisions can interact with the result.']},
{heading:'Tax Bracket Optimizer — topic 3',text:['Bracket room is the amount of additional taxable ordinary income that can fit before reaching the next threshold. That concept is useful for Roth conversions, realizing income, exercising certain compensation, or deciding when to take deductible contributions. If a taxpayer has $15,000 of room remaining in a chosen bracket, converting $30,000 of pre-tax retirement assets may cause part of the conversion to spill into the next marginal rate.']},
{heading:'Tax Bracket Optimizer — topic 4',text:['Pre-tax retirement contributions can reduce current taxable income subject to contribution and plan rules. Their value depends on the marginal tax rate avoided today and the future tax treatment of withdrawals. Do not contribute merely to stay below a bracket if the cash is needed for higher-priority goals. Likewise, a deductible expense does not save its full amount; the tax reduction is generally a fraction determined by the applicable marginal rate and other limitations.']},
{heading:'Tax Bracket Optimizer — topic 5',text:['Long-term capital gains use a separate rate structure that can interact with ordinary taxable income. Additional ordinary income can consume space that otherwise supports a lower capital-gains rate, and realizing gains can affect other thresholds. A simple ordinary-bracket optimizer may not capture that stacking. Taxpayers with substantial investment income should model ordinary and preferential-rate income together.']},
{heading:'Tax Bracket Optimizer — topic 6',text:['Credits differ from deductions. A deduction reduces taxable income, while a tax credit generally reduces tax liability directly subject to its rules. Some credits phase out as income rises, creating effective marginal rates that are not visible from the statutory bracket alone. Healthcare subsidies, education benefits, child-related credits, and other provisions can make the real cost of additional income higher or lower than the headline bracket.']},
{heading:'Tax Bracket Optimizer — topic 7',text:['A practical year-end review estimates full-year income, subtracts expected adjustments and deductions, and compares projected taxable income with current-year thresholds for the correct filing status. Then test controllable actions such as retirement contributions, HSA contributions if eligible, charitable timing, business expenses where legitimate, or Roth conversions. The action must have economic substance; spending one dollar merely to save a fraction of a dollar in tax is not a gain.']},
{heading:'Tax Bracket Optimizer — topic 8',text:['Tax thresholds change over time and legislation can alter rates, deductions, and phaseouts. Use the calculator’s stated tax year and verify current IRS figures before acting. For multi-year planning, compare scenarios because accelerating income into one year can reduce income in another. The best tax plan minimizes total after-tax cost across years while still serving the taxpayer’s financial goals.']},
]},
'paycheck-contribution-optimizer':{title:'Paycheck Contribution Optimizer',sections:[
{heading:'Paycheck Contribution Optimizer — topic 1',text:['Payroll contribution planning translates annual retirement and benefit goals into per-paycheck elections. Start with the number of pay periods remaining, year-to-date contributions, and the applicable annual limit. The basic required contribution per remaining paycheck is the remaining desired annual amount divided by remaining pay periods. That arithmetic becomes more important after a midyear job change, bonus, or missed contribution because simply using the original percentage can undershoot or overshoot the target.',
{heading:'True-up provisions protect some front-loaded savers',text:['A plan with a true-up can make an additional employer contribution after year-end when an employee contributed enough overall but missed match in certain pay periods because of front-loading. Eligibility, timing, and employment requirements vary. Do not assume a true-up exists because another employer offered one. If there is no true-up, spread employee deferrals so at least enough contribution remains each paycheck to capture the full available match.',
{heading:'Percentage elections need a rounding buffer',text:['Payroll systems often round contributions to cents and can stop or cap an election when the annual limit is reached. If the goal is to hit a limit exactly, a percentage calculated from estimated pay may miss because of overtime, unpaid leave or payroll rounding. Revisit the election several paychecks before year-end. A small final adjustment is easier than correcting an excess after the calendar year closes.']},]},
{heading:'HSA payroll contributions have unique value',text:['When eligible HSA contributions are made through a cafeteria-plan payroll arrangement, they can receive federal income-tax advantages and may also avoid Social Security and Medicare taxes, subject to current rules. A direct after-tax HSA contribution can still be deductible for federal income tax but may not receive the same payroll-tax treatment. That can make payroll funding especially efficient, although state tax treatment varies.']},
{heading:'FSA elections require spending awareness',text:['Healthcare FSAs generally involve annual elections and plan-specific carryover or grace-period rules. Overfunding can risk forfeiture under use-it-or-lose-it provisions, while underfunding sacrifices some tax advantage. Estimate predictable eligible expenses such as prescriptions, copays, dental work, or vision costs before setting the election. A contribution optimizer should not automatically maximize an FSA simply because a legal limit exists.']},
{heading:'Bonuses can disrupt percentage elections',text:['If a plan applies the same deferral percentage to bonus pay, a large bonus can consume annual contribution room earlier than expected. Some payroll systems allow a separate bonus election; others do not. Before a known bonus, project year-end contributions using both regular and supplemental pay. This is particularly important when the employee is trying to capture match through the final paycheck or coordinate deferrals after changing employers.']},
{heading:'Reconcile the final paystub',text:['At year-end, compare actual employee deferrals and HSA or FSA contributions with the intended totals. Payroll rounding, unpaid leave, variable compensation, election delays, and job changes can create small differences. Correcting an excess contribution can involve deadlines and administrative steps, so early detection is valuable. Keep records from every employer rather than assuming one payroll portal contains the full-year picture.']},]},
{heading:'Paycheck Contribution Optimizer — topic 2',text:['401(k), 403(b), HSA, and FSA limits are separate and have different eligibility and employer rules. Do not combine them into one annual ceiling. Employee elective-deferral limits can also interact across multiple employers, while employer contributions may be subject to separate overall plan limits. Catch-up contributions depend on age and current law. A calculator labeled 2026 should use verified 2026 limits and should distinguish individual from family HSA coverage.']},
{heading:'Paycheck Contribution Optimizer — topic 3',text:['Employer match mechanics can determine the best payroll cadence. Some plans match each paycheck and do not provide a year-end true-up. An employee who maxes the 401(k) too early could stop contributing later and miss matching dollars. Other plans true up contributions after year-end if eligibility requirements are met. Read the summary plan description before front-loading. Capturing the full match is often the first optimization constraint.']},
{heading:'Paycheck Contribution Optimizer — topic 4',text:['Contribution percentages are applied to plan-defined eligible compensation, which may treat salary, overtime, commissions, and bonuses differently. If payroll asks for a percentage rather than a dollar amount, divide the desired paycheck contribution by expected eligible gross pay. Recalculate when compensation changes. A large bonus can cause an unexpected contribution unless the plan allows separate bonus elections.']},
{heading:'Paycheck Contribution Optimizer — topic 5',text:['Traditional pre-tax contributions can reduce federal taxable wages for income-tax purposes, while Roth contributions generally do not, though payroll-tax treatment can differ by contribution type. HSA contributions made through a qualifying cafeteria plan can have additional payroll-tax advantages in many cases. FSA elections reduce eligible taxable wages but are governed by use and carryover rules. The optimizer should show cash-flow impact rather than assuming every contributed dollar reduces take-home pay by a full dollar.']},
{heading:'Paycheck Contribution Optimizer — topic 6',text:['HSA eligibility requires qualifying high-deductible health coverage and compliance with other rules. Annual limits can be prorated in some circumstances, with special rules such as the last-month rule and testing period. An HSA should not be treated as available merely because the employer offers one. FSA and HSA combinations can also be restricted, although limited-purpose FSAs can coexist in appropriate circumstances.']},
{heading:'Paycheck Contribution Optimizer — topic 7',text:['A midyear job change deserves a fresh calculation. Employee 401(k) deferrals made at the old employer generally count toward the same individual annual elective-deferral limit at the new employer. Payroll systems do not automatically know what was contributed elsewhere. Keep final paystubs and enter year-to-date amounts manually. HSA contributions from all sources also need coordination against the annual eligible limit.']},
{heading:'Paycheck Contribution Optimizer — topic 8',text:['Suppose an employee wants to reach a $24,000 annual deferral target, has already contributed $9,000, and has 10 paychecks left. The remaining $15,000 requires $1,500 per paycheck. If expected eligible pay is $6,000 each period, that corresponds to 25%. Before setting it, verify that payroll permits the percentage, that the election will still capture employer match, and that bonus or irregular pay will not cause an unintended early maximum.']},
{heading:'Paycheck Contribution Optimizer — topic 9',text:['Do not optimize tax savings at the expense of cash-flow stability. Payroll contributions compete with rent, debt, emergency reserves, and near-term expenses. A mathematically maximal contribution can create credit-card debt, which may be counterproductive. The useful plan captures valuable employer benefits, respects legal limits, and fits a sustainable household budget.']},
]},
'real-estate-syndication-calculator':{title:'Real Estate Syndication Calculator',sections:[
{heading:'Real Estate Syndication Calculator — topic 1',text:['A real-estate syndication pools investor equity under a sponsor or general partner that acquires and operates a property. Limited partners typically contribute capital and receive economic rights defined by the operating agreement, while the sponsor sources the deal, arranges financing, executes the business plan, and manages disposition. Calculator outputs such as cash-on-cash return, equity multiple, preferred return, and IRR describe different aspects of that investment and should not be treated as interchangeable.',
{heading:'Cap rate links NOI and value',text:['Capitalization rate is commonly expressed as net operating income divided by property value. Rearranged, value equals NOI divided by cap rate. If projected NOI is $1 million and the exit cap is 5%, the implied value is $20 million; at 6%, it is about $16.7 million. That sensitivity shows why a one-percentage-point exit-cap change can dominate investor returns. Stress exit assumptions instead of relying only on the sponsor’s base case.',
{heading:'Construction and lease-up risk deserve separate scenarios',text:['Value-add deals often assume renovation spending will raise rents or occupancy. Delays can create a double hit: capital is spent while improved units are not yet producing projected revenue. Model slower renovation pace, higher construction cost and lower rent premiums separately. If the deal’s return collapses under modest execution slippage, the base IRR may be compensating investors for substantial operational risk rather than representing a stable yield.']},
{heading:'Refinance proceeds are not operating income',text:['Some syndications plan a cash-out refinance after improving the property. Refinance proceeds can return investor capital without a sale, but they create or increase debt and do not represent property operating profit. A large tax-deferred cash distribution can look attractive while leaving the property more leveraged. After modeling refinance cash, also model the higher debt service, maturity and downside equity cushion that remain.']},
{heading:'Reserves protect distributions from normal volatility',text:['A property with no operating or capital reserve may distribute more cash early but require a capital call when roofs, HVAC systems, tenant improvements or vacancies arise. Review the sponsor’s reserve assumptions and whether reserves are funded at closing or from operations. The calculator should not treat every dollar of projected property cash as distributable if prudent reserves are part of the business plan.']},
{heading:'Compare sponsor projections with deal documents',text:['Marketing materials may summarize a target IRR or equity multiple, while the operating agreement controls legal economics. Verify preferred-return language, waterfall tiers, fees, capital-call rights, voting provisions and transfer restrictions in the actual documents. Small wording differences can change who receives cash and when. Calculator inputs should come from the governing terms, not from a simplified headline in a pitch deck.']},]},
{heading:'NOI is before debt service',text:['Net operating income generally reflects property revenue minus operating expenses before mortgage payments, depreciation, income tax, and many capital items. Investors should verify what the sponsor includes in NOI and whether reserves and recurring capital needs are adequate. A property can report growing NOI while investor distributions remain weak because debt service, renovations, or reserves consume cash. Do not equate property-level NOI growth with distributable cash.']},
{heading:'Capital calls can change investor return',text:['Some operating agreements allow additional capital calls when renovations exceed budget, occupancy falls, or refinancing is unavailable. Investors who do not contribute may face dilution, penalties, or other consequences depending on the documents. A base-case calculator that assumes the initial contribution is the only equity can overstate IRR if later cash is required. Include plausible follow-on contributions in downside scenarios.']},
{heading:'Sponsor promote creates alignment and conflict',text:['A promote gives the sponsor a larger share of profits after specified hurdles and can reward strong performance. It also makes waterfall details economically important. Review whether hurdles are based on IRR, equity multiple, preferred return, or another measure; whether there is a catch-up; and whether fees are earned regardless of performance. Alignment should be assessed across the whole compensation structure, not inferred from one promote percentage.']},
{heading:'Compare realized and unrealized returns',text:['Quarterly reports may show estimated property values and projected investor returns before a sale occurs. Those values are not realized cash and can change with cap rates, leasing, financing, or market conditions. Track actual distributions separately from sponsor valuation marks. The final equity multiple and IRR are only known after all material cash flows, including disposition and final expenses, are complete.']},]},
{heading:'Real Estate Syndication Calculator — topic 2',text:['Cash-on-cash return usually compares annual cash distributions with invested equity. It is easy to understand but ignores the timing of later sale proceeds and can vary by year. Equity multiple compares total cash returned with total equity invested; a 2.0× multiple means two dollars returned for each dollar invested, including return of capital, but says nothing about whether that took three years or ten. IRR incorporates timing and therefore can distinguish those cases.']},
{heading:'Real Estate Syndication Calculator — topic 3',text:['A preferred return is an allocation rule, not a guaranteed bond coupon. The operating agreement may provide that investors receive distributions up to a stated preferred return before the sponsor participates in certain profit splits. The preference can be cumulative or noncumulative and may be calculated on contributed capital, unreturned capital, or another base. If property cash flow is insufficient, the unpaid preference may accrue depending on the agreement; it is not necessarily paid currently.']},
{heading:'Real Estate Syndication Calculator — topic 4',text:['Waterfalls determine how cash is split after specified hurdles. A simple structure might pay investors a preferred return and return capital, then split remaining profits 70/30 between limited partners and sponsor. More complex waterfalls can include catch-up tiers and changing promote percentages at IRR hurdles. A calculator must mirror the actual waterfall to estimate investor proceeds. Applying one flat sponsor split to every dollar can materially misstate returns.']},
{heading:'Real Estate Syndication Calculator — topic 5',text:['Debt magnifies property-level outcomes. Higher leverage can increase equity returns when operations and sale values are strong, but it also increases fixed debt service and refinancing risk. Floating-rate loans can make projected cash flow sensitive to interest rates, while short maturities create balloon or refinance risk. Review loan-to-value, debt-service coverage, rate caps, maturity, extension options, and recourse provisions rather than evaluating projected investor returns in isolation.']},
{heading:'Real Estate Syndication Calculator — topic 6',text:['The exit assumption often drives a large share of projected profit. Sponsors may model a future sale price by applying an exit capitalization rate to projected net operating income. A lower exit cap creates a higher value, all else equal. Assuming both strong NOI growth and cap-rate compression can make a pro forma aggressive. Run a sensitivity matrix with lower NOI and a higher exit cap to see whether the investment still produces acceptable proceeds.']},
{heading:'Real Estate Syndication Calculator — topic 7',text:['Fees reduce investor economics. Acquisition, asset-management, construction-management, financing, disposition, property-management, and refinance fees can all appear depending on the deal. Some are paid to third parties and some to sponsor affiliates. Understand which fees are already reflected in property cash flow and which are taken from investor capital or sale proceeds so they are not omitted or double-counted.']},
{heading:'Real Estate Syndication Calculator — topic 8',text:['Tax reporting can include depreciation, interest expense, passive losses, capital gains, and depreciation-related gain treatment, but investor outcomes depend on individual circumstances and the partnership’s allocations. A K-1 tax loss does not mean the investment lost cash, and a cash distribution is not automatically taxable income in the same amount. State filing obligations can arise when properties operate outside the investor’s home state.']},
{heading:'Real Estate Syndication Calculator — topic 9',text:['Suppose an investor contributes $100,000, receives $6,000 annually for four years, and receives $150,000 including final operating cash and sale proceeds in year five. Total cash returned is $174,000, producing a 1.74× gross equity multiple. IRR will depend on the exact dates of those cash flows. If the $150,000 exit payment arrives two years later, the equity multiple is unchanged but IRR falls substantially. That illustrates why both metrics belong in the analysis.']},
{heading:'Real Estate Syndication Calculator — topic 10',text:['Illiquidity is a core risk. Private syndication interests may have no practical secondary market, and transfer restrictions can apply. Investors should not commit cash needed for near-term expenses. Sponsor quality, reporting, conflicts of interest, capital-call provisions, reserves, property concentration, local market conditions, and the business plan can matter as much as the modeled return. A calculator can stress the economics; due diligence determines whether the assumptions deserve confidence.']},
]},
'health-insurance-deductible-calculator':{title:'Health Insurance Deductible Calculator',sections:[
{heading:'Health Insurance Deductible Calculator — topic 1',text:['A health-insurance deductible is the amount of covered healthcare cost a member generally pays before the plan begins sharing many types of costs, but real plans contain exceptions. Preventive care may be covered before the deductible, office visits may use copays, prescription drugs can have a separate deductible, and family plans can use embedded individual deductibles or an aggregate family deductible. Read the summary of benefits rather than assuming every medical dollar follows one simple sequence.',
{heading:'Copays can bypass the deductible',text:['Some plans charge a fixed copay for primary care, specialists, urgent care, or prescriptions even before the deductible is met. Others make the member pay the negotiated cost until deductible. Entering every visit as deductible spending can therefore overstate cost for copay-first plans. Build the scenario from the plan’s benefit grid: service category, whether deductible applies, then copay or coinsurance.',
{heading:'Cash-flow timing matters even with the same annual total',text:['A high-deductible plan can require several thousand dollars early in January before the household has accumulated HSA contributions for the year. Two plans with similar annual expected cost can therefore create very different liquidity needs. Compare not only annual totals but also the maximum bill the household could face before sufficient savings accumulate. An HSA balance carried from prior years can reduce that risk.']},
{heading:'Use claims history carefully',text:['Prior-year claims can help identify recurring prescriptions, therapy, specialist visits or planned procedures, but one year is not a forecast. A healthy household can have an unexpected emergency, while a high-cost year may not repeat. Build expected use from known recurring care, then test a high-use case up to the plan’s eligible out-of-pocket maximum. This balances personal evidence with uncertainty instead of assuming next year exactly repeats last year.']},
{heading:'Premium tax credits change marketplace comparisons',text:['For eligible Marketplace coverage, premium tax credits can make the household’s net premium differ substantially from the plan’s full sticker premium, and income changes can affect eligibility and reconciliation. A deductible calculator that accepts only gross premium may not capture this. Use the actual net premium expected for the household and tax year when comparing plans, and revisit the estimate if projected household income changes materially.']},]},
{heading:'Allowed amount matters more than billed charge',text:['An in-network provider may bill $1,000 while the insurer’s contracted allowed amount is $600. Cost sharing is generally calculated from the allowed amount under the plan, not the original sticker price. Before the deductible, the member may owe the negotiated $600 rather than the full billed amount. Estimates based on public chargemaster prices can therefore be far from the actual plan cost.']},
{heading:'Out-of-network exposure can exceed the maximum',text:['The plan’s in-network out-of-pocket maximum does not necessarily cap every dollar a patient can owe. Out-of-network balance billing, noncovered care, premiums, and certain other charges may sit outside the protected total, subject to applicable federal and state surprise-billing rules. Someone who needs a particular specialist should check network status instead of relying on the calculator’s maximum as a universal worst-case number.']},
{heading:'Plan year resets change procedure timing',text:['Deductibles and out-of-pocket accumulators usually reset at the start of a new plan year. A course of treatment spanning December and January can therefore encounter two deductibles. Conversely, once a member has already reached the out-of-pocket maximum late in a year, additional covered in-network care may have much lower marginal cost. Medical necessity should drive care, but understanding the reset can improve financial planning for elective timing.']},
{heading:'Worst-case annual cost includes premium',text:['For a simplified in-network comparison, a useful upper-bound planning number is annual employee premium plus the applicable out-of-pocket maximum, adjusted for employer account contributions where appropriate. This is not a guarantee because excluded services and out-of-network charges can exceed it, but it provides a consistent risk measure between plans. Compare that worst case with the expected-use case and the household’s ability to absorb a large early-year bill.']},]},
{heading:'Health Insurance Deductible Calculator — topic 2',text:['Coinsurance begins after applicable deductible requirements for many services. If a plan has 20% member coinsurance, the insurer generally pays 80% of the allowed amount and the member pays 20% until the out-of-pocket maximum is reached, subject to plan rules. The relevant number is the insurer-negotiated allowed amount for in-network care, not necessarily the provider’s sticker charge. Out-of-network billing can follow different rules and may expose the patient to amounts that do not count toward the in-network maximum.']},
{heading:'Health Insurance Deductible Calculator — topic 3',text:['The out-of-pocket maximum caps the member’s eligible in-network cost sharing for covered essential benefits during the plan year under applicable rules. Premiums do not count toward that maximum, and neither do many noncovered services or amounts outside network protections. A calculator should therefore keep annual premium separate from medical cost sharing, then add them when comparing total annual household cost.']},
{heading:'Health Insurance Deductible Calculator — topic 4',text:['For plan comparison, calculate annual premiums first. A plan costing $150 more per month requires $1,800 more premium per year before anyone receives care. Then model low, moderate, and high healthcare-use scenarios using deductible, copays, coinsurance, and out-of-pocket limits. A high-deductible plan can be cheaper in a low-use year but more expensive when substantial care occurs; a richer plan can reverse that relationship.']},
{heading:'Health Insurance Deductible Calculator — topic 5',text:['Employer HSA contributions change the effective cost of an HSA-eligible high-deductible plan. If one plan includes a $1,000 employer HSA deposit, subtract that employer value when comparing economic cost, while recognizing that HSA eligibility has specific federal requirements. Employee HSA contributions are the employee’s own money and should not be counted as an insurance cost; they move cash into a tax-advantaged account that can be used for qualified expenses.']},
{heading:'Health Insurance Deductible Calculator — topic 6',text:['Family structure matters. With embedded deductibles, one family member may satisfy an individual threshold and begin receiving plan cost sharing before the entire family deductible is met. Under an aggregate design, the family may need to meet the combined threshold first. Similar distinctions can apply to out-of-pocket limits. A calculator that uses one family number should state which structure it assumes.']},
{heading:'Health Insurance Deductible Calculator — topic 7',text:['Suppose Plan A charges $400 per month with a $2,000 deductible, 20% coinsurance, and a $6,000 out-of-pocket maximum. Plan B charges $550 per month with a $750 deductible and lower cost sharing. Plan B starts $1,800 behind on annual premium. For a low-use household, it may never recover that premium difference; for a year with surgery or expensive treatment, lower cost sharing may offset it. Calculate both the expected case and the worst eligible in-network case.']},
{heading:'Health Insurance Deductible Calculator — topic 8',text:['Prescription coverage can dominate the result for someone taking expensive medication. Formularies, tiers, copays, coinsurance, specialty-drug rules, prior authorization, and manufacturer assistance can differ between plans. Do not assume the medical deductible fully describes drug cost. Check the exact medication on each current formulary and confirm whether its cost sharing counts toward the same deductible and out-of-pocket maximum.']},
{heading:'Health Insurance Deductible Calculator — topic 9',text:['A deductible calculator cannot predict healthcare needs. Use known recurring care, planned procedures, pregnancy expectations, chronic-condition treatment, and medication needs to build scenarios, then include uncertainty. Network access is also a nonfinancial constraint: a cheaper plan is not equivalent if key physicians or hospitals are out of network. The best comparison combines annual premium, modeled cost sharing, employer account contributions, network fit, and risk tolerance.']},
]},
}
export function CalculatorBatch43DeepDive({slug}:{slug:string}){const g=guides[slug];if(!g)return null;return <section className="mx-auto max-w-5xl px-4 py-10"><div className="rounded-2xl border border-gray-200 bg-white p-6 md:p-8"><h2 className="text-2xl md:text-3xl font-bold text-gray-900">{g.title}: Detailed Guide</h2><p className="mt-3 text-gray-700 leading-7">Use this guide to understand the calculator's subject-specific mechanics, assumptions, interpretation and limitations.</p><div className="mt-8 space-y-8">{g.sections.map((s,i)=><article key={i}><h3 className="text-xl font-semibold text-gray-900">{s.heading}</h3>{s.text.map((p,j)=><p key={j} className="mt-3 text-gray-700 leading-7">{p}</p>)}</article>)}</div></div></section>}
